(861429, 97750, 13365, '<td valign="top">I would of perfered the face being closer to the flower, seems to be too much of a void. Nice lighting however! 6</td>', 'I would of perfered the face being closer to the flower, seems to be too much of a void. Nice lighting however! 6', '2004-08-16 11:55:35.000000', NULL, 1),
(861430, 97676, 7152, '<td valign="top">ohhh .. this is neat !! .. not sure if I like the cobweb ...well .. I do and I don''t .. the web works with the plant life .. plants are the anchors for webs ... but then I don''t like it b/c there isn''t enough of it .. so I''m not really sure if I see it as a distraction .. or a little compoment of the overall picture.</td>', 'ohhh .. this is neat !! .. not sure if I like the cobweb ...well .. I do and I don''t .. the web works with the plant life .. plants are the anchors for webs ... but then I don''t like it b/c there isn''t enough of it .. so I''m not really sure if I see it as a distraction .. or a little compoment of the overall picture.', '2004-08-16 11:55:58.000000', NULL, 1),
(861431, 97333, 13365, '<td valign="top">Simple yet effective, well done!</td>', 'Simple yet effective, well done!', '2004-08-16 11:55:59.000000', NULL, 1),
(861434, 97126, 7152, '<td valign="top">very nice duot-one .. but I dont think u should have cut out the flower on the right.</td>', 'very nice duot-one .. but I dont think u should have cut out the flower on the right.', '2004-08-16 11:56:54.000000', NULL, 1),
(861436, 96652, 7152, '<td valign="top">very very nice ... simple ... but elegant .. classy ... amazing (9)</td>', 'very very nice ... simple ... but elegant .. classy ... amazing (9)', '2004-08-16 11:57:30.000000', NULL, 1),
(861438, 97801, 13365, '<td valign="top">Great sunflower image, seems a bit heavy on the dodge and burn, Im seeing too much of a halo effect around the flower that seem very unnatural, Good job!</td>', 'Great sunflower image, seems a bit heavy on the dodge and burn, Im seeing too much of a halo effect around the flower that seem very unnatural, Good job!', '2004-08-16 11:58:22.000000', NULL, 1),
(861439, 97336, 7152, '<td valign="top">HA !!! .. this is great .. hahahahhah ... how did you get that shadow ! .. 10 !!</td>', 'HA !!! .. this is great .. hahahahhah ... how did you get that shadow ! .. 10 !!', '2004-08-16 11:58:22.000000', NULL, 1),
(861449, 96914, 25150, '<td valign="top">Thats great,<br/>It got my highest score!</td>', 'Thats great,It got my highest score!', '2004-08-16 12:04:10.000000', NULL, 1),
