INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(861518, 97526, 24454, '<td valign="top">I like this picture a lot.  I like the way the flower rises out of the "blur" to a sharp bright focus.</td>', 'I like this picture a lot.  I like the way the flower rises out of the "blur" to a sharp bright focus.', '2004-08-16 12:52:07.000000', NULL, 1),
(861530, 97971, 19608, '<td valign="top">Wonderful scene taken with the perfect exposure.  I have problem with the composition - think you have included too much in the image.  It is also distracting to have the white flowers cut in half at the base.  The border does absolutely nothing to help the image.</td>', 'Wonderful scene taken with the perfect exposure.  I have problem with the composition - think you have included too much in the image.  It is also distracting to have the white flowers cut in half at the base.  The border does absolutely nothing to help the image.', '2004-08-16 12:57:39.000000', NULL, 1),
(861537, 97558, 19608, '<td valign="top">Great intrepretation and presentation.  The transition from green to dried is marvelous.  The white background is perfect as is exposure.  I really like the leaves that have shadows - maybe stronger side-lighting would have applified the shadows, making it even stronger.  One of my top picks so far.</td>', 'Great intrepretation and presentation.  The transition from green to dried is marvelous.  The white background is perfect as is exposure.  I really like the leaves that have shadows - maybe stronger side-lighting would have applified the shadows, making it even stronger.  One of my top picks so far.', '2004-08-16 13:01:26.000000', NULL, 1),
(861538, 97190, 200, '<td valign="top">nice to see something a little different :)</td>', 'nice to see something a little different :)', '2004-08-16 13:02:12.000000', NULL, 1),
(861539, 97781, 13365, '<td valign="top">Im sure you''ll get this a bunch, but it''s way too dark, all the detail is lost. And yes, my monitor is calibrated!</td>', 'Im sure you''ll get this a bunch, but it''s way too dark, all the detail is lost. And yes, my monitor is calibrated!', '2004-08-16 13:02:52.000000', NULL, 1),
(861540, 97286, 19608, '<td valign="top">Excellent - great interaction between the roots and the marbles.  Nice colors.  I think it would be much better without the (dirty) metal pan at the base.</td>', 'Excellent - great interaction between the roots and the marbles.  Nice colors.  I think it would be much better without the (dirty) metal pan at the base.', '2004-08-16 13:03:19.000000', NULL, 1),
(861547, 97120, 200, '<td valign="top">very nice. Looks like a drawing. I like this quite a lot and refreshing to see a different perspective. Good luck.</td>', 'very nice. Looks like a drawing. I like this quite a lot and refreshing to see a different perspective. Good luck.', '2004-08-16 13:07:09.000000', NULL, 1),
(861551, 96652, 19608, '<td valign="top">Simple - and very effective.  Black background is perfect.  Composition could not be better.  Title is imaginative - but where is the am/pm indicator? (I wonder if some won''t even notice the "clock hands"!)  The border is just "ok" - think it should either be a uniform width - or if not, larger at the base only.  Try it with a much thinner, uniform frame.  Should finish well up in the pack - I really like it.</td>', 'Simple - and very effective.  Black background is perfect.  Composition could not be better.  Title is imaginative - but where is the am/pm indicator? (I wonder if some won''t even notice the "clock hands"!)  The border is just "ok" - think it should either be a uniform width - or if not, larger at the base only.  Try it with a much thinner, uniform frame.  Should finish well up in the pack - I really like it.', '2004-08-16 13:08:26.000000', NULL, 1),
(861553, 97347, 19608, '<td valign="top">Wonderful lighting.  I like the repeating shape in the background but wonder if it would be stronger if it were more green (instead of gray.)  Textures are amazing.</td>', 'Wonderful lighting.  I like the repeating shape in the background but wonder if it would be stronger if it were more green (instead of gray.)  Textures are amazing.', '2004-08-16 13:10:04.000000', NULL, 1),
(861555, 97668, 200, '<td valign="top">oh my....thats funny</td>', 'oh my....thats funny', '2004-08-16 13:11:11.000000', NULL, 1),
(861560, 97930, 200, '<td valign="top">ewwwwwww</td>', 'ewwwwwww', '2004-08-16 13:12:46.000000', NULL, 1),
(861563, 97700, 200, '<td valign="top">nice perspective</td>', 'nice perspective', '2004-08-16 13:13:26.000000', NULL, 1),
(861568, 97190, 19608, '<td valign="top">Delightful whirpool of colors!  This is an exceptional image - well composed and exposed.  I expect the DPC voters won''t "get it" which is a real shame.  The weakest link is the title, but that is so minor... but try something like "Fantasia" or "Poetry in motion."  Overall, I hope this does well - it is so artistic and creative.</td>', 'Delightful whirpool of colors!  This is an exceptional image - well composed and exposed.  I expect the DPC voters won''t "get it" which is a real shame.  The weakest link is the title, but that is so minor... but try something like "Fantasia" or "Poetry in motion."  Overall, I hope this does well - it is so artistic and creative.', '2004-08-16 13:22:06.000000', NULL, 1),
(861571, 97763, 24454, '<td valign="top">Great idea!  Love this one!</td>', 'Great idea!  Love this one!', '2004-08-16 13:22:25.000000', NULL, 1),
(861574, 96723, 19608, '<td valign="top">He he.  Nice intrepretation of the challenge.  White background works very well - making the colors really stand out.  Cropped a bit close on the top - the leaf up there needs more breathing room.</td>', 'He he.  Nice intrepretation of the challenge.  White background works very well - making the colors really stand out.  Cropped a bit close on the top - the leaf up there needs more breathing room.', '2004-08-16 13:24:35.000000', NULL, 1),
(861575, 97297, 24454, '<td valign="top">Great picture!  This one would make a neat "Wall Picture"  :)</td>', 'Great picture!  This one would make a neat "Wall Picture"  :)', '2004-08-16 13:24:41.000000', NULL, 1),
(861577, 97515, 19608, '<td valign="top">Great lighting.  It''s fun to wander around in the image, but it probably should have one "key element."  Excellent exposure.</td>', 'Great lighting.  It''s fun to wander around in the image, but it probably should have one "key element."  Excellent exposure.', '2004-08-16 13:26:23.000000', NULL, 1),
(861579, 97671, 19608, '<td valign="top">Superb scene - very "painterly."   Somehow the work you did on the sky (dodging, burning?) looks very artifical.  (If that''s not the case feel free to PM me.)<br/>Exposure on the ground area (buildings, flowers, etc) is perfect.  Did you try a graduated ND filter?  Strong entry.</td>', 'Superb scene - very "painterly."   Somehow the work you did on the sky (dodging, burning?) looks very artifical.  (If that''s not the case feel free to PM me.)Exposure on the ground area (buildings, flowers, etc) is perfect.  Did you try a graduated ND filter?  Strong entry.', '2004-08-16 13:31:28.000000', NULL, 1),
(861580, 97331, 2764, '<td valign="top">ooohh you are right, petal perfect - too much water is my only complaint - 9</td>', 'ooohh you are right, petal perfect - too much water is my only complaint - 9', '2004-08-16 13:32:36.000000', NULL, 1),
(861581, 97700, 19608, '<td valign="top">Wonderful cone flower in a great composition.  The repeating pattern of the second flower works well.  I do not like the man-made background at all - it adds unnecessary square shapes and a color that detracts from the image.  But - the main cone flower is so perfect and powerful, so it still gets high marks.</td>', 'Wonderful cone flower in a great composition.  The repeating pattern of the second flower works well.  I do not like the man-made background at all - it adds unnecessary square shapes and a color that detracts from the image.  But - the main cone flower is so perfect and powerful, so it still gets high marks.', '2004-08-16 13:34:16.000000', NULL, 1),
(861585, 97314, 19608, '<td valign="top">Subject = great.  Exposure = right on.  Lighting = ok - but mabe a bit softer would be better (the shadows are very black.)  Composition:  Would be much stronger taken on a diagonal.  Prognosis = well high in the pack.</td>', 'Subject = great.  Exposure = right on.  Lighting = ok - but mabe a bit softer would be better (the shadows are very black.)  Composition:  Would be much stronger taken on a diagonal.  Prognosis = well high in the pack.', '2004-08-16 13:37:25.000000', NULL, 1),
(861587, 97843, 24454, '<td valign="top">Nice picture!  I like the way there are no footprints in the sand.  Gives it a real professional looking quality.</td>', 'Nice picture!  I like the way there are no footprints in the sand.  Gives it a real professional looking quality.', '2004-08-16 13:40:23.000000', NULL, 1),
(861588, 96645, 19608, '<td valign="top">Great idea, title, composition and exposure.  Unfortunately - your filesize of only 40k caused all kinds of terrible compression "uglies" on the background.  Try to use as much of the allowed 150k as you can.</td>', 'Great idea, title, composition and exposure.  Unfortunately - your filesize of only 40k caused all kinds of terrible compression "uglies" on the background.  Try to use as much of the allowed 150k as you can.', '2004-08-16 13:40:50.000000', NULL, 1),
(861590, 96797, 19608, '<td valign="top">Wonderful subject - nice setup and exposure.  Compositionally - I think it is MUCH stronger as a square image by cropping from the top.  The banding in the golden /brown areas is unfortunate.</td>', 'Wonderful subject - nice setup and exposure.  Compositionally - I think it is MUCH stronger as a square image by cropping from the top.  The banding in the golden /brown areas is unfortunate.', '2004-08-16 13:44:03.000000', NULL, 1),
(861594, 97336, 24454, '<td valign="top">VERY creative!   Good job.  10</td>', 'VERY creative!   Good job.  10', '2004-08-16 13:48:44.000000', NULL, 1),
(861598, 96655, 24454, '<td valign="top">VERY pretty!</td>', 'VERY pretty!', '2004-08-16 13:50:45.000000', NULL, 1),
(861602, 97828, 24454, '<td valign="top">What a great picture!  Yep.  This one definitely has the "Wow Factor"!  10</td>', 'What a great picture!  Yep.  This one definitely has the "Wow Factor"!  10', '2004-08-16 13:54:24.000000', NULL, 1),
(861606, 97207, 24454, '<td valign="top">Very pretty!</td>', 'Very pretty!', '2004-08-16 13:55:46.000000', NULL, 1),
(861614, 97447, 20673, '<td valign="top">Absolutely Beautiful!</td>', 'Absolutely Beautiful!', '2004-08-16 14:01:24.000000', NULL, 1),
(861616, 97875, 24454, '<td valign="top">I really love this picture!  This looks like a "Wall Picture", and I especially like the originality &amp; the fact that there was n''ery a hint of a close-up of a flower or leaf in it :)   Easy 10!</td>', 'I really love this picture!  This looks like a "Wall Picture", and I especially like the originality & the fact that there was n''ery a hint of a close-up of a flower or leaf in it :)   Easy 10!', '2004-08-16 14:02:37.000000', NULL, 1),
(861617, 97992, 20673, '<td valign="top">The truck in the background takes away from the beauty of the sunflowers.</td>', 'The truck in the background takes away from the beauty of the sunflowers.', '2004-08-16 14:02:48.000000', NULL, 1),
(861621, 97984, 20673, '<td valign="top">I hope this one wins ( even though I want to - LOL ) This is a breathtaking photo!!</td>', 'I hope this one wins ( even though I want to - LOL ) This is a breathtaking photo!!', '2004-08-16 14:04:45.000000', NULL, 1),
(861624, 97875, 18799, '<td valign="top">Botany is a pretty small part of this photo, IMO</td>', 'Botany is a pretty small part of this photo, IMO', '2004-08-16 14:05:20.000000', NULL, 1),
(861637, 97700, 20673, '<td valign="top">simple and very pretty!</td>', 'simple and very pretty!', '2004-08-16 14:10:21.000000', NULL, 1),
(861638, 97799, 20673, '<td valign="top">Very sharp and crisp detail - wonderful comp - Great shot!!!</td>', 'Very sharp and crisp detail - wonderful comp - Great shot!!!', '2004-08-16 14:11:26.000000', NULL, 1),
(861640, 97759, 20673, '<td valign="top">Gorgeous color!</td>', 'Gorgeous color!', '2004-08-16 14:12:06.000000', NULL, 1),
(861643, 97576, 20673, '<td valign="top">This is so lovely and appealing - what a wonderful gorgeous picture - congrats!</td>', 'This is so lovely and appealing - what a wonderful gorgeous picture - congrats!', '2004-08-16 14:14:37.000000', NULL, 1),
(861652, 97041, 20673, '<td valign="top">WOW! So pretty - it looks like its lit up - beautiful!</td>', 'WOW! So pretty - it looks like its lit up - beautiful!', '2004-08-16 14:16:28.000000', NULL, 1),
(861657, 96914, 20673, '<td valign="top">cool!</td>', 'cool!', '2004-08-16 14:17:23.000000', NULL, 1),
(861663, 98016, 20673, '<td valign="top">perfect comp and light!</td>', 'perfect comp and light!', '2004-08-16 14:19:41.000000', NULL, 1),
(861666, 97347, 20673, '<td valign="top">nicely unique - great photo!</td>', 'nicely unique - great photo!', '2004-08-16 14:20:50.000000', NULL, 1),
(861674, 97830, 20673, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2004-08-16 14:23:28.000000', NULL, 1),
(861690, 97812, 10080, '<td valign="top">I dont get the title? But this is a nice shot!</td>', 'I dont get the title? But this is a nice shot!', '2004-08-16 14:32:47.000000', NULL, 1),
(861691, 97912, 10080, '<td valign="top">Good job, nice composition, good colors, nice detail!</td>', 'Good job, nice composition, good colors, nice detail!', '2004-08-16 14:34:17.000000', NULL, 1),
(861692, 97944, 10080, '<td valign="top">nice job!</td>', 'nice job!', '2004-08-16 14:35:23.000000', NULL, 1),
(861694, 97412, 18799, '<td valign="top">Tough time of day for photos  5</td>', 'Tough time of day for photos  5', '2004-08-16 14:36:33.000000', NULL, 1),
(861698, 98011, 10080, '<td valign="top">I do like your colors and composition, but overall it just looks fake?</td>', 'I do like your colors and composition, but overall it just looks fake?', '2004-08-16 14:37:09.000000', NULL, 1),
(861699, 97671, 21430, '<td valign="top">The burning in this image seems a bit overdone and also lacking in a few spots, like on the the left part of the image where the tree ''mates'' with the roof of the building. This image just feels over processed.<br/> <br/>  I do like the contrast you are reaching for with this, but the changes in lighting between one spot and another are to drastic and sudden.</td>', 'The burning in this image seems a bit overdone and also lacking in a few spots, like on the the left part of the image where the tree ''mates'' with the roof of the building. This image just feels over processed.   I do like the contrast you are reaching for with this, but the changes in lighting between one spot and another are to drastic and sudden.', '2004-08-16 14:37:15.000000', NULL, 1),
(861708, 98017, 10080, '<td valign="top">nice shot! I like the detail ,composition, and overall warmth</td>', 'nice shot! I like the detail ,composition, and overall warmth', '2004-08-16 14:40:17.000000', NULL, 1),
(861714, 97558, 4008, '<td valign="top">great idea. Good "botany" image with a real theme to show the change of leave color in autumn.</td>', 'great idea. Good "botany" image with a real theme to show the change of leave color in autumn.', '2004-08-16 14:45:46.000000', NULL, 1),
(861715, 97979, 4008, '<td valign="top">For me the fence looks to be the main subject, maybe from the other side it would have been more botany</td>', 'For me the fence looks to be the main subject, maybe from the other side it would have been more botany', '2004-08-16 14:46:49.000000', NULL, 1),
(861717, 97551, 4008, '<td valign="top">I find the top left flower competing for attention with the main flower, would have liked a tighter crop. But great colors and good depth, very attractive.</td>', 'I find the top left flower competing for attention with the main flower, would have liked a tighter crop. But great colors and good depth, very attractive.', '2004-08-16 14:48:30.000000', NULL, 1),
(861719, 97470, 7628, '<td valign="top">These a great colors, and the close composition empashises them as does the contract with the vivid blue sky.  You''ve got some nice detail about halfway up the petals, but the tips of the petals aren''t as sharp - a greater DOF would make everything crisp - I''d also skip the frame - it is kinda neat, but the picture is even better.</td>', 'These a great colors, and the close composition empashises them as does the contract with the vivid blue sky.  You''ve got some nice detail about halfway up the petals, but the tips of the petals aren''t as sharp - a greater DOF would make everything crisp - I''d also skip the frame - it is kinda neat, but the picture is even better.', '2004-08-16 14:48:45.000000', NULL, 1),
(861720, 97982, 4008, '<td valign="top">simple, strong, attractive, good fit to challenge theme.</td>', 'simple, strong, attractive, good fit to challenge theme.', '2004-08-16 14:49:04.000000', NULL, 1),
(861723, 97190, 20673, '<td valign="top">Am I allowed to say that I like this? Obviously first glance says "oh its blurry and out of focus" but this is a nicely different abstract in my opinion. I love how the colors and shapes all meld together and I can almost feel the motion of the flowers. So I said it and all can berate me later - I like this one.</td>', 'Am I allowed to say that I like this? Obviously first glance says "oh its blurry and out of focus" but this is a nicely different abstract in my opinion. I love how the colors and shapes all meld together and I can almost feel the motion of the flowers. So I said it and all can berate me later - I like this one.', '2004-08-16 14:50:41.000000', NULL, 1),
(861725, 97443, 7628, '<td valign="top">An interesting subject - stands out amid all these flowers and vivid greens.  I wish all the details on the leaf were clearer, And I''m not sure about the composition that crops the leaf slightly on the right - perhaps crop more or include the whole leaf - as is it is not very interesting.  I do like the gray background  -  the textural deails at the top left as a bit distracting - perhaps a little burning (more burning than you''ve done) or some spot editing.  I do like the comination of the bright orange of the leaf and the dark gray of the background.</td>', 'An interesting subject - stands out amid all these flowers and vivid greens.  I wish all the details on the leaf were clearer, And I''m not sure about the composition that crops the leaf slightly on the right - perhaps crop more or include the whole leaf - as is it is not very interesting.  I do like the gray background  -  the textural deails at the top left as a bit distracting - perhaps a little burning (more burning than you''ve done) or some spot editing.  I do like the comination of the bright orange of the leaf and the dark gray of the background.', '2004-08-16 14:53:09.000000', NULL, 1),
(861729, 97997, 4008, '<td valign="top">not sure what you want to show here, too much going on. A choice of some large leaves, or a flower, a more concentrated image would have been more appealing.</td>', 'not sure what you want to show here, too much going on. A choice of some large leaves, or a flower, a more concentrated image would have been more appealing.', '2004-08-16 14:55:04.000000', NULL, 1),
(861732, 97752, 7628, '<td valign="top">This is a very busy image.  Lots of colors and textures that compete for your eyes attention.  Your title points to the twisting bark - perhaps a composition without the new growth would be better?  Or if you wish us to look at the green of the new leaves, perhaps burning in the bark behind them or blurring the background a bit?</td>', 'This is a very busy image.  Lots of colors and textures that compete for your eyes attention.  Your title points to the twisting bark - perhaps a composition without the new growth would be better?  Or if you wish us to look at the green of the new leaves, perhaps burning in the bark behind them or blurring the background a bit?', '2004-08-16 14:56:40.000000', NULL, 1),
(861738, 97861, 7628, '<td valign="top">High key works nicely with the test tube and flask - gives a very "steril scientific" feel.  The red of the rose leaves stands out nicely.  I wish the leaves in the magnifing glass were lit and focused to show a deeper color and detail of texture - as is we cannot see those leaves much better than the ones behind.  Nice subject and composition tho''</td>', 'High key works nicely with the test tube and flask - gives a very "steril scientific" feel.  The red of the rose leaves stands out nicely.  I wish the leaves in the magnifing glass were lit and focused to show a deeper color and detail of texture - as is we cannot see those leaves much better than the ones behind.  Nice subject and composition tho''', '2004-08-16 14:59:38.000000', NULL, 1),
(861742, 97781, 4008, '<td valign="top">I really like the different approach from the usual "veins" images where everything is show clearly.</td>', 'I really like the different approach from the usual "veins" images where everything is show clearly.', '2004-08-16 15:01:37.000000', NULL, 1),
(861743, 97934, 19608, '<td valign="top">Nice capture!  It all works very well except the right side.  There I''d recommend cropping out the brown bud and just a bit more.  You may want to crop the same amount from the left side behind the hummer. Exposure is right on.  Excellent choice of shutter speed.</td>', 'Nice capture!  It all works very well except the right side.  There I''d recommend cropping out the brown bud and just a bit more.  You may want to crop the same amount from the left side behind the hummer. Exposure is right on.  Excellent choice of shutter speed.', '2004-08-16 15:02:35.000000', NULL, 1),
(861744, 97858, 7628, '<td valign="top">The yellow and blue contrasts nicely - makes for a cartoony feel.  Fun - especially those bee wings.  The flowers and bee work well for the topic - tells something about plant life, even if the feel is more science fiction than fact!  You may find this radical color manipulation to be unpopular with voters. I wish the plants were sharper.  I might crop a bit on the top so the viewer''s eyes don''t travel up there for too long.</td>', 'The yellow and blue contrasts nicely - makes for a cartoony feel.  Fun - especially those bee wings.  The flowers and bee work well for the topic - tells something about plant life, even if the feel is more science fiction than fact!  You may find this radical color manipulation to be unpopular with voters. I wish the plants were sharper.  I might crop a bit on the top so the viewer''s eyes don''t travel up there for too long.', '2004-08-16 15:03:42.000000', NULL, 1),
(861746, 97442, 4008, '<td valign="top">a great subject with attractive color and nice transparency. For me the image is let down by its composition. A bit messy. I think you should have chosen three leaves or so and make a more simple composition.</td>', 'a great subject with attractive color and nice transparency. For me the image is let down by its composition. A bit messy. I think you should have chosen three leaves or so and make a more simple composition.', '2004-08-16 15:05:25.000000', NULL, 1),
(861748, 97883, 4008, '<td valign="top">beautiful documentary style image, for a flower encyclopedia.</td>', 'beautiful documentary style image, for a flower encyclopedia.', '2004-08-16 15:06:31.000000', NULL, 1),
(861751, 98004, 7628, '<td valign="top">The narrow DOF makes the red spikes seem delicate rather than threatening.  You could create a bit more contract by boosting the saturation a bit - the red and green will contrast nicely. Perhaps a bit of buri=ning to emphasize the shadows and structure. I like your close composition and how it shows the structure of the plant.  I would crop in both on the right and top to loose that piece of ground in the corner.  This should put the center of the plant more on the "thirds line" which would make a more dynamic shape.</td>', 'The narrow DOF makes the red spikes seem delicate rather than threatening.  You could create a bit more contract by boosting the saturation a bit - the red and green will contrast nicely. Perhaps a bit of buri=ning to emphasize the shadows and structure. I like your close composition and how it shows the structure of the plant.  I would crop in both on the right and top to loose that piece of ground in the corner.  This should put the center of the plant more on the "thirds line" which would make a more dynamic shape.', '2004-08-16 15:08:53.000000', NULL, 1),
(861754, 97801, 4008, '<td valign="top">I think the subject is very standard, colors a great, but don''t like the halo around the flower or the dead leave hanging down, middle of flower is too dark. Overall still attractive though.</td>', 'I think the subject is very standard, colors a great, but don''t like the halo around the flower or the dead leave hanging down, middle of flower is too dark. Overall still attractive though.', '2004-08-16 15:10:01.000000', NULL, 1),
(861756, 97605, 7628, '<td valign="top">The tilted composition helps the viewer relate to the plant - I feel a pit like I''m haging in the corner of a wall.  I like the high contract and deep saturation.  The green of your plant stands out well even in the busy background, and the contrast between the natural and the manmade is is drawn nicey with the diagonal line in the middle of the photo.  The cap of the water pipe balances the plant - fitting and ironic, since the plant needs water but wont get it from there!</td>', 'The tilted composition helps the viewer relate to the plant - I feel a pit like I''m haging in the corner of a wall.  I like the high contract and deep saturation.  The green of your plant stands out well even in the busy background, and the contrast between the natural and the manmade is is drawn nicey with the diagonal line in the middle of the photo.  The cap of the water pipe balances the plant - fitting and ironic, since the plant needs water but wont get it from there!', '2004-08-16 15:12:49.000000', NULL, 1),
(861759, 97992, 4008, '<td valign="top">suggest you try to avoid a car in the background next time, it spoils the image for me.</td>', 'suggest you try to avoid a car in the background next time, it spoils the image for me.', '2004-08-16 15:14:25.000000', NULL, 1),
(861761, 97470, 19608, '<td valign="top">Woderful specimen, colors, composition, lighting, and exposure.  Could use just a bit more DoF - if that was possible.  Although I won''t take off any points - the border is a disaster.</td>', 'Woderful specimen, colors, composition, lighting, and exposure.  Could use just a bit more DoF - if that was possible.  Although I won''t take off any points - the border is a disaster.', '2004-08-16 15:15:19.000000', NULL, 1),
(861764, 97851, 7628, '<td valign="top">I like the Blue and the green halves of the photo and how they pick up on the horizontal lines of the barbed wire.  With the narrow focus these things make a nice environment for the delicate flowers whose whiteness and sharpness makes them pop out of the picture.  Nie title as well.</td>', 'I like the Blue and the green halves of the photo and how they pick up on the horizontal lines of the barbed wire.  With the narrow focus these things make a nice environment for the delicate flowers whose whiteness and sharpness makes them pop out of the picture.  Nie title as well.', '2004-08-16 15:15:35.000000', NULL, 1),
(861765, 97802, 4008, '<td valign="top">just beautiful.</td>', 'just beautiful.', '2004-08-16 15:17:10.000000', NULL, 1),
(861769, 97330, 7628, '<td valign="top">I love the blue and the pattern in the water drop!  I like the subtle and abstract forms of the tout of focus flowers as a back drop, but I crop in more from the top and the left - removing the bright bits of the stems that distract the eye.  Beautiful shot!</td>', 'I love the blue and the pattern in the water drop!  I like the subtle and abstract forms of the tout of focus flowers as a back drop, but I crop in more from the top and the left - removing the bright bits of the stems that distract the eye.  Beautiful shot!', '2004-08-16 15:18:22.000000', NULL, 1),
(861787, 97305, 19608, '<td valign="top">You have a pleasing scene here - the deer are a nice touch.  Unfortunately - the overexposure pretty much ruins an otherwise great image.</td>', 'You have a pleasing scene here - the deer are a nice touch.  Unfortunately - the overexposure pretty much ruins an otherwise great image.', '2004-08-16 15:35:02.000000', NULL, 1),
(861790, 97608, 19608, '<td valign="top">THe bark is superb but the background, especially the white diagonal, destroys your image.  Go back - try in in late afternoon lighting.</td>', 'THe bark is superb but the background, especially the white diagonal, destroys your image.  Go back - try in in late afternoon lighting.', '2004-08-16 15:36:26.000000', NULL, 1),
(861791, 97285, 18197, '<td valign="top">Focus on the petals is good. Composition is fine but perhaps a bit busy. For me, the B&amp;W detracts from the image rather than helping. The background is distracting ... too blurry to be in focus. Too in focus to be shallow DOF.</td>', 'Focus on the petals is good. Composition is fine but perhaps a bit busy. For me, the B&W detracts from the image rather than helping. The background is distracting ... too blurry to be in focus. Too in focus to be shallow DOF.', '2004-08-16 15:36:44.000000', NULL, 1),
(861793, 97912, 18197, '<td valign="top">Very nice colors and focus. Composition is very good although it feels a little crowded at the top.</td>', 'Very nice colors and focus. Composition is very good although it feels a little crowded at the top.', '2004-08-16 15:37:47.000000', NULL, 1),
(861795, 96947, 19608, '<td valign="top">Excellent colors and pattern.  Perfect exposure.  Try it with the main vein on a diagonal - I think you will like it better.</td>', 'Excellent colors and pattern.  Perfect exposure.  Try it with the main vein on a diagonal - I think you will like it better.', '2004-08-16 15:38:45.000000', NULL, 1),
(861796, 97877, 18197, '<td valign="top">Technical capture is nearly perfect. But composition seems overly busy to me.</td>', 'Technical capture is nearly perfect. But composition seems overly busy to me.', '2004-08-16 15:38:49.000000', NULL, 1),
(861799, 98013, 18197, '<td valign="top">Very nice focus and DOF. Good centered composition. Subject may be more interesting to you than to me.</td>', 'Very nice focus and DOF. Good centered composition. Subject may be more interesting to you than to me.', '2004-08-16 15:40:08.000000', NULL, 1),
(861800, 97799, 19608, '<td valign="top">Great lighting and setup.  Black background is stunning with the green leaves. Composition could not be any better.</td>', 'Great lighting and setup.  Black background is stunning with the green leaves. Composition could not be any better.', '2004-08-16 15:41:13.000000', NULL, 1),
(861803, 97966, 18197, '<td valign="top">Exceptional focus. Contrast and levels are terrific. The black area to the left detracts from a top 10 entry IMO. I am wondering what a full color image would have looked like. Usually desaturating beautifully colored flowers feels wrong to me, but in this case, I think it increased the drama of the picture. Good job.</td>', 'Exceptional focus. Contrast and levels are terrific. The black area to the left detracts from a top 10 entry IMO. I am wondering what a full color image would have looked like. Usually desaturating beautifully colored flowers feels wrong to me, but in this case, I think it increased the drama of the picture. Good job.', '2004-08-16 15:43:03.000000', NULL, 1),
(861804, 97961, 19608, '<td valign="top">Good idea and it looks to be a nice image.  But it is way too small to judge with any precision.  You need to use as much of the allowed 640 pixels and 150k as you can.</td>', 'Good idea and it looks to be a nice image.  But it is way too small to judge with any precision.  You need to use as much of the allowed 640 pixels and 150k as you can.', '2004-08-16 15:43:16.000000', NULL, 1),
(861805, 98001, 18197, '<td valign="top">Good technical capture but composition is weak. Odd color for a background but the color wheel contrast with the green makes it pop a bit.</td>', 'Good technical capture but composition is weak. Odd color for a background but the color wheel contrast with the green makes it pop a bit.', '2004-08-16 15:45:01.000000', NULL, 1),
(861807, 98014, 19608, '<td valign="top">Great specimem - taken in nice flat lighting.  Colors are great - even the decaying leaves.  I''d feel a bit better about it if the mushroom were more off centered - move it to the right in the frame.</td>', 'Great specimem - taken in nice flat lighting.  Colors are great - even the decaying leaves.  I''d feel a bit better about it if the mushroom were more off centered - move it to the right in the frame.', '2004-08-16 15:46:03.000000', NULL, 1),
(861810, 98020, 24016, '<td valign="top">what is the significance of white on the left here? the tomato looks great with the green too but the white on the left takes away from the image and the "botany" aspect in my opinion.</td>', 'what is the significance of white on the left here? the tomato looks great with the green too but the white on the left takes away from the image and the "botany" aspect in my opinion.', '2004-08-16 15:46:19.000000', NULL, 1),
(861811, 97915, 18197, '<td valign="top">I like the composition and colors. The fruit seems a little washed out. Interesting DOF.</td>', 'I like the composition and colors. The fruit seems a little washed out. Interesting DOF.', '2004-08-16 15:46:26.000000', NULL, 1),
(861814, 97930, 18197, '<td valign="top">This looks like a picture of fauna, not flora. Good colors, focus, DOF and background raise the score.</td>', 'This looks like a picture of fauna, not flora. Good colors, focus, DOF and background raise the score.', '2004-08-16 15:48:15.000000', NULL, 1),
(861815, 97483, 19608, '<td valign="top">Excellent!  Perfect colors that go together - in a great composition.  Just get rid of the glinty leaf just behind the purple blossom.</td>', 'Excellent!  Perfect colors that go together - in a great composition.  Just get rid of the glinty leaf just behind the purple blossom.', '2004-08-16 15:48:30.000000', NULL, 1),
(861816, 97944, 18197, '<td valign="top">Very very nice. I have long admired her art and you have done it justice. Great capture.</td>', 'Very very nice. I have long admired her art and you have done it justice. Great capture.', '2004-08-16 15:49:02.000000', NULL, 1),
(861818, 97558, 18197, '<td valign="top">Nice capture conveying an interesting idea. Colors are terrific. Lighting is okay but possibly a little flat and you''ve almost lost the shadows. Maybe the single light source was too bright and multiple less intense sources would have improved.</td>', 'Nice capture conveying an interesting idea. Colors are terrific. Lighting is okay but possibly a little flat and you''ve almost lost the shadows. Maybe the single light source was too bright and multiple less intense sources would have improved.', '2004-08-16 15:51:13.000000', NULL, 1),
(861822, 97934, 18197, '<td valign="top">Nicely captures the challenge theme. Technically excellent photo and I''m sure it was difficult to capture. Addition of the hummingbird is a nice touch and having it dark against the dark background was a subtle choice. Perhaps too subtle, since it''s pretty dark on my monitor.</td>', 'Nicely captures the challenge theme. Technically excellent photo and I''m sure it was difficult to capture. Addition of the hummingbird is a nice touch and having it dark against the dark background was a subtle choice. Perhaps too subtle, since it''s pretty dark on my monitor.', '2004-08-16 15:53:04.000000', NULL, 1),
(861824, 97671, 17547, '<td valign="top">Great job, love the colors and thyme. 10</td>', 'Great job, love the colors and thyme. 10', '2004-08-16 15:53:19.000000', NULL, 1),
(861825, 97750, 19608, '<td valign="top">Excellent setup - the black background works exceptionally well.  The lighting is perfect, both on the flower and the model''s face. I think it would be stronger if your model was closer to the flower.</td>', 'Excellent setup - the black background works exceptionally well.  The lighting is perfect, both on the flower and the model''s face. I think it would be stronger if your model was closer to the flower.', '2004-08-16 15:53:38.000000', NULL, 1),
(861827, 98002, 18197, '<td valign="top">Nice colors and DOF. Composition weakens the overall power of the photo.</td>', 'Nice colors and DOF. Composition weakens the overall power of the photo.', '2004-08-16 15:53:55.000000', NULL, 1),
(861829, 97350, 18197, '<td valign="top">I really like the subject and the composition. However the colors feel a bit wahed out and flat. The horizontal line in the background doesn''t help. I wonder if you altered the angle of the photo or put the subject closer to the wall to avoid the line whether it would improve it.</td>', 'I really like the subject and the composition. However the colors feel a bit wahed out and flat. The horizontal line in the background doesn''t help. I wonder if you altered the angle of the photo or put the subject closer to the wall to avoid the line whether it would improve it.', '2004-08-16 15:55:58.000000', NULL, 1),
(861831, 97875, 18197, '<td valign="top">Althugh there is flora in the photo, it doesn''t feel to me like it meets the challenge very well. Otherwise the picture is quite good and raises the score some.</td>', 'Althugh there is flora in the photo, it doesn''t feel to me like it meets the challenge very well. Otherwise the picture is quite good and raises the score some.', '2004-08-16 15:57:04.000000', NULL, 1),
(861833, 97652, 327, '<td valign="top">Interesting, unique composition. Maybe a bit more care so her hair didn''t show through. Also I''d of liked to be level with her eye. I do like this.</td>', 'Interesting, unique composition. Maybe a bit more care so her hair didn''t show through. Also I''d of liked to be level with her eye. I do like this.', '2004-08-16 15:58:21.000000', NULL, 1),
(861834, 97598, 18197, '<td valign="top">Good job of geting close to the subject. Composition mostly works well but the white spot hurts IMO. It looks like you were just a bit too close for a really sharp focus. I wonder what ISO you were shooting. I wonder because the image seems a bit grainy to me.</td>', 'Good job of geting close to the subject. Composition mostly works well but the white spot hurts IMO. It looks like you were just a bit too close for a really sharp focus. I wonder what ISO you were shooting. I wonder because the image seems a bit grainy to me.', '2004-08-16 15:59:23.000000', NULL, 1),
(861835, 97875, 327, '<td valign="top">Nice take on the challenge. Unusual find, and interesting to view.</td>', 'Nice take on the challenge. Unusual find, and interesting to view.', '2004-08-16 15:59:36.000000', NULL, 1),
(861840, 97979, 18197, '<td valign="top">Nice subject. Well captured. Two suggestions: 1) This might have been more interesting and pleasing if you shot it early morning or late afternoon with longer shadows and more saturated colors; and 2) The composition with the middle post dead in the middle of the picture detracts a bit. Suggest moving to the left or right  bit and taking the picture from a different height (higher or closer to the ground).</td>', 'Nice subject. Well captured. Two suggestions: 1) This might have been more interesting and pleasing if you shot it early morning or late afternoon with longer shadows and more saturated colors; and 2) The composition with the middle post dead in the middle of the picture detracts a bit. Suggest moving to the left or right  bit and taking the picture from a different height (higher or closer to the ground).', '2004-08-16 16:02:43.000000', NULL, 1),
(861841, 97782, 327, '<td valign="top">Beautiful lighting.</td>', 'Beautiful lighting.', '2004-08-16 16:03:08.000000', NULL, 1),
(861842, 97337, 18197, '<td valign="top">Elegantly simple image and well captured. Desaturation weakens it IMO.</td>', 'Elegantly simple image and well captured. Desaturation weakens it IMO.', '2004-08-16 16:03:35.000000', NULL, 1),
(861844, 97783, 18197, '<td valign="top">Bet the degree of difficulty here was high. Good job on an interesting idea. However I can''t find anything in really sharp focus. The composition feels scattered (maybe it was supposed to) to me but it weakens my response to the image.</td>', 'Bet the degree of difficulty here was high. Good job on an interesting idea. However I can''t find anything in really sharp focus. The composition feels scattered (maybe it was supposed to) to me but it weakens my response to the image.', '2004-08-16 16:06:04.000000', NULL, 1),
(861847, 97643, 18197, '<td valign="top">Classic capture of a classic subject. Interestingly, for me the background may be the photo''s best feature. It conveys a "Tuscan Sun" sort of feeling. Nice job with that.</td>', 'Classic capture of a classic subject. Interestingly, for me the background may be the photo''s best feature. It conveys a "Tuscan Sun" sort of feeling. Nice job with that.', '2004-08-16 16:07:18.000000', NULL, 1),
(861850, 97810, 18197, '<td valign="top">Good colors and comp. The shallow DOF field means many of the blossom and blossom parts are not in sharp focus. It''s an ideosyncracy of mine but I like to have something in razor sharp focus and it bothers the heck out of me when I can''t do it in my own photos all the time.</td>', 'Good colors and comp. The shallow DOF field means many of the blossom and blossom parts are not in sharp focus. It''s an ideosyncracy of mine but I like to have something in razor sharp focus and it bothers the heck out of me when I can''t do it in my own photos all the time.', '2004-08-16 16:09:24.000000', NULL, 1),
(861851, 97604, 18197, '<td valign="top">Nice subject and composition in spite of its dead center approach. Focus on the center bud is nice and sharp. Colors feel a little flat ot me. What was your lighting setup?</td>', 'Nice subject and composition in spite of its dead center approach. Focus on the center bud is nice and sharp. Colors feel a little flat ot me. What was your lighting setup?', '2004-08-16 16:10:52.000000', NULL, 1),
(861852, 97984, 19608, '<td valign="top">Ahh - the tiger lily is so great a specimen.  It really needs a plain non-distracting background unlike the lichen behind the stamens now.  The orange color is stunning.  Border does not need the white lines.</td>', 'Ahh - the tiger lily is so great a specimen.  It really needs a plain non-distracting background unlike the lichen behind the stamens now.  The orange color is stunning.  Border does not need the white lines.', '2004-08-16 16:10:57.000000', NULL, 1),
(861856, 97447, 4517, '<td valign="top">Great clarity and colours and everything.</td>', 'Great clarity and colours and everything.', '2004-08-16 16:12:41.000000', NULL, 1),
(861857, 97736, 19608, '<td valign="top">This scene is so pleasing -  I want to reach in and yank thet tool out of there.  (I really hope you took it without the clipper.)</td>', 'This scene is so pleasing -  I want to reach in and yank thet tool out of there.  (I really hope you took it without the clipper.)', '2004-08-16 16:12:49.000000', NULL, 1),
(861859, 98014, 18197, '<td valign="top">I''d never eat that mushroom. It looks radioactive. Seriously, it''s a nice photo which I like a lot. It could be a bit busy around the edges but the desaturation helps some. I am sure getting sharp contrast between mushroom and grean stuff in background was hard.  But in the end, I can''t quite get past the radio active color of the mushroom.</td>', 'I''d never eat that mushroom. It looks radioactive. Seriously, it''s a nice photo which I like a lot. It could be a bit busy around the edges but the desaturation helps some. I am sure getting sharp contrast between mushroom and grean stuff in background was hard.  But in the end, I can''t quite get past the radio active color of the mushroom.', '2004-08-16 16:13:51.000000', NULL, 1),
(861860, 97992, 4517, '<td valign="top">Nice sharp and colourful sunflowers but background distracting.<br/><br/><i>Message edited by author 2004-08-28 16:32:52.</i></td>', 'Nice sharp and colourful sunflowers but background distracting.', '2004-08-16 16:14:06.000000', '2004-08-28 17:32:52.000000', 1),
(861862, 97333, 18197, '<td valign="top">Superb shot which nicely delivers on the Botony theme. Translucence of the leaf is very effective. Razor sharp focus is fantastic. How you did it with the dark dark background is a mystery I hope you''ll do a tutorial on.</td>', 'Superb shot which nicely delivers on the Botony theme. Translucence of the leaf is very effective. Razor sharp focus is fantastic. How you did it with the dark dark background is a mystery I hope you''ll do a tutorial on.', '2004-08-16 16:15:28.000000', NULL, 1),
(861863, 97936, 18197, '<td valign="top">Love the composition and colors. Focus is great. Well done.</td>', 'Love the composition and colors. Focus is great. Well done.', '2004-08-16 16:16:19.000000', NULL, 1),
(861864, 97966, 19608, '<td valign="top">An excellent specimen - well rendered.  I''d crop quite a bit from the bottom so the the edge is just below the small whitest leaf.  To me, that''s a much stronger composition.  As is - it''s still an excellent submission.</td>', 'An excellent specimen - well rendered.  I''d crop quite a bit from the bottom so the the edge is just below the small whitest leaf.  To me, that''s a much stronger composition.  As is - it''s still an excellent submission.', '2004-08-16 16:18:26.000000', NULL, 1),
(861866, 97751, 18197, '<td valign="top">For some reason this doesn''t rsonate with me much. I guess I don''t understand what you''re trying to say or the emotional payload you''re trying to deliver. There are a few technical quibbles but in the end, my discomfort is with the subject and comp I think.</td>', 'For some reason this doesn''t rsonate with me much. I guess I don''t understand what you''re trying to say or the emotional payload you''re trying to deliver. There are a few technical quibbles but in the end, my discomfort is with the subject and comp I think.', '2004-08-16 16:19:36.000000', NULL, 1),
(861871, 97676, 18197, '<td valign="top">Among the best I''ve seen so far. I was attracted to the thumbnail, and upon opening it, I was far from disappointed. Very nice image in every way. Even the spider web seems well thought and it''s addative rather than distracting.</td>', 'Among the best I''ve seen so far. I was attracted to the thumbnail, and upon opening it, I was far from disappointed. Very nice image in every way. Even the spider web seems well thought and it''s addative rather than distracting.', '2004-08-16 16:21:14.000000', NULL, 1),
(861876, 97812, 24642, '<td valign="top">Great simplicity.  Perfect timing for the Olympics.</td>', 'Great simplicity.  Perfect timing for the Olympics.', '2004-08-16 16:26:56.000000', NULL, 1),
(861877, 97303, 3087, '<td valign="top">Nice use of sunset as backlight - I like that it''s dark enough to give silhouettes but light enough to see shadows on the grass.</td>', 'Nice use of sunset as backlight - I like that it''s dark enough to give silhouettes but light enough to see shadows on the grass.', '2004-08-16 16:27:55.000000', NULL, 1),
(861878, 97843, 3087, '<td valign="top">Nice curve to the flower patch. Lovely colours.</td>', 'Nice curve to the flower patch. Lovely colours.', '2004-08-16 16:28:57.000000', NULL, 1),
(861879, 97948, 3087, '<td valign="top">Nice processing. Looks like a postcard. Very pretty.</td>', 'Nice processing. Looks like a postcard. Very pretty.', '2004-08-16 16:29:37.000000', NULL, 1),
(861881, 97314, 3087, '<td valign="top">Very strong shadows, seem oo black to me, a little unnatural which is probably the effect you were going for but for me that strong black overwhelms the main subject a little. Nice strong graphic shape though.</td>', 'Very strong shadows, seem oo black to me, a little unnatural which is probably the effect you were going for but for me that strong black overwhelms the main subject a little. Nice strong graphic shape though.', '2004-08-16 16:30:44.000000', NULL, 1),
(861883, 97297, 3087, '<td valign="top">Nice sense of depth and good decision to crop so close.</td>', 'Nice sense of depth and good decision to crop so close.', '2004-08-16 16:31:04.000000', NULL, 1),
(861892, 97333, 3087, '<td valign="top">Nice lighting, makes it glow. Nice simply composition too. Need a touch more light on stem from front as it''s not really visible very easily and I think it would balance leaf more if it were.</td>', 'Nice lighting, makes it glow. Nice simply composition too. Need a touch more light on stem from front as it''s not really visible very easily and I think it would balance leaf more if it were.', '2004-08-16 16:35:23.000000', NULL, 1),
(861894, 97447, 19608, '<td valign="top">This is an excellent composition with the water adding some nice shapes.  The flat lighting worked ok - but this would really pop if there were some strong back lighting in the center area of the flower.  Nice colors in the flower and the background.</td>', 'This is an excellent composition with the water adding some nice shapes.  The flat lighting worked ok - but this would really pop if there were some strong back lighting in the center area of the flower.  Nice colors in the flower and the background.', '2004-08-16 16:36:12.000000', NULL, 1),
(861895, 97347, 3087, '<td valign="top">Great lighting, really delineates the edges of the leaves. Love the faint background branch too. Lovely composition with strong diagonal and with that little bit of interest in what would be the black half.</td>', 'Great lighting, really delineates the edges of the leaves. Love the faint background branch too. Lovely composition with strong diagonal and with that little bit of interest in what would be the black half.', '2004-08-16 16:36:48.000000', NULL, 1),
(861897, 97330, 3087, '<td valign="top">Lovely use of colour and light to create an almost abstract imag and yet one with recognisable subject too. Purple hue o stem is a touch too strange but otherwise love it.</td>', 'Lovely use of colour and light to create an almost abstract imag and yet one with recognisable subject too. Purple hue o stem is a touch too strange but otherwise love it.', '2004-08-16 16:38:27.000000', NULL, 1),
(861900, 97333, 19608, '<td valign="top">Superb lighting and study of texture.  I would normally suggest a more diagonal composition for a shot like this... but NOT for this one.  The very formal, perfectly centered and vertical composition works perfectly.  You found the right time to ignore some rules and go with instict.  The black background really sets off the green.  Finally, the apeture you used appears perfect!  Great job, thanks for sharing.</td>', 'Superb lighting and study of texture.  I would normally suggest a more diagonal composition for a shot like this... but NOT for this one.  The very formal, perfectly centered and vertical composition works perfectly.  You found the right time to ignore some rules and go with instict.  The black background really sets off the green.  Finally, the apeture you used appears perfect!  Great job, thanks for sharing.', '2004-08-16 16:39:32.000000', NULL, 1),
(861901, 97576, 3087, '<td valign="top">Lovely muted image with colour only really in the plant. Nice choice to freeze water motion too.</td>', 'Lovely muted image with colour only really in the plant. Nice choice to freeze water motion too.', '2004-08-16 16:39:36.000000', NULL, 1),
(861903, 97252, 19608, '<td valign="top">Very nice seeing and presentation.  The formal, centered and vertical composition works well for this one.  Nice background and colors make it really stunning.</td>', 'Very nice seeing and presentation.  The formal, centered and vertical composition works well for this one.  Nice background and colors make it really stunning.', '2004-08-16 16:41:15.000000', NULL, 1),
(861907, 97973, 19608, '<td valign="top">Great title!  Did you give the flower a hairdo?? Perfect exposure - nice colors.    Background is ok - slightly distracting - but not much you could have done.</td>', 'Great title!  Did you give the flower a hairdo?? Perfect exposure - nice colors.    Background is ok - slightly distracting - but not much you could have done.', '2004-08-16 16:42:48.000000', NULL, 1),
(861910, 97558, 3087, '<td valign="top">Lovely colours and clean presentation.</td>', 'Lovely colours and clean presentation.', '2004-08-16 16:43:47.000000', NULL, 1),
(861912, 97520, 3087, '<td valign="top">Lovely use of dappled light rather than even studio lighting. Imparts a strong mood to the shot.</td>', 'Lovely use of dappled light rather than even studio lighting. Imparts a strong mood to the shot.', '2004-08-16 16:44:16.000000', NULL, 1),
(861914, 97177, 3087, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2004-08-16 16:44:30.000000', NULL, 1),
(861915, 98007, 19608, '<td valign="top">I really want to like this as a whole as the muted colors with the B&amp;W are really pleasant. But it is so busy - with too many really bright areas in the background, I find it hard to score it very high.</td>', 'I really want to like this as a whole as the muted colors with the B&W are really pleasant. But it is so busy - with too many really bright areas in the background, I find it hard to score it very high.', '2004-08-16 16:44:45.000000', NULL, 1),
(861917, 97088, 3087, '<td valign="top">Beautiful textures and I love the lines all sweeping inwards towards the stamen from all around the frame. I wish there weren''t that black area at the lower right... I often like imperfect specimens - but here I''d like the full frame to be petal surface.</td>', 'Beautiful textures and I love the lines all sweeping inwards towards the stamen from all around the frame. I wish there weren''t that black area at the lower right... I often like imperfect specimens - but here I''d like the full frame to be petal surface.', '2004-08-16 16:45:32.000000', NULL, 1),
(861922, 97803, 3087, '<td valign="top">I love this! It''s just beautiful in form and colour and DOF. I love the contrast between straight, cold metal and spiralling organic vine. Wonderfully cropped too. Excellent.</td>', 'I love this! It''s just beautiful in form and colour and DOF. I love the contrast between straight, cold metal and spiralling organic vine. Wonderfully cropped too. Excellent.', '2004-08-16 16:48:17.000000', NULL, 1),
(861926, 97126, 3087, '<td valign="top">Nice use of top down to use circle to add composition. Stark nature of pot rim contrasts beautifully with intricate shapes and textures of the plant and rocks.</td>', 'Nice use of top down to use circle to add composition. Stark nature of pot rim contrasts beautifully with intricate shapes and textures of the plant and rocks.', '2004-08-16 16:50:55.000000', NULL, 1),
(861928, 97493, 14476, '<td valign="top">This is such a charming picture.  If it was mine, I''d probably take away quite a lot of that border/fade treatment, as the image stands beautifully without it.  Still, a well thought out and goodlooking entry.</td>', 'This is such a charming picture.  If it was mine, I''d probably take away quite a lot of that border/fade treatment, as the image stands beautifully without it.  Still, a well thought out and goodlooking entry.', '2004-08-16 16:51:29.000000', NULL, 1),
(861929, 97836, 3087, '<td valign="top">Different and I like how this one really suggests the study of plants, i.e. botany, more than just a picture of a plant itself.</td>', 'Different and I like how this one really suggests the study of plants, i.e. botany, more than just a picture of a plant itself.', '2004-08-16 16:51:58.000000', NULL, 1),
(861936, 97744, 3087, '<td valign="top">BEAUTIFUL! I love the detail and texture on the leaves and the light and shadow on the petals. The composition feels balanced. Black and white is SO perfect. EXCELLENT!</td>', 'BEAUTIFUL! I love the detail and texture on the leaves and the light and shadow on the petals. The composition feels balanced. Black and white is SO perfect. EXCELLENT!', '2004-08-16 16:56:29.000000', NULL, 1),
(861938, 97558, 19959, '<td valign="top">This is excellent. Not sure how you managed it but this is perfect for the challenge. A large number of entried ''fail'' to convey Botany. This works though on all levels.</td>', 'This is excellent. Not sure how you managed it but this is perfect for the challenge. A large number of entried ''fail'' to convey Botany. This works though on all levels.', '2004-08-16 16:58:08.000000', NULL, 1),
(861940, 97747, 19959, '<td valign="top">Great....</td>', 'Great....', '2004-08-16 16:58:20.000000', NULL, 1),
(861944, 97041, 3087, '<td valign="top">Lovely - is there a candle inside? That''s how it looks. Very nice.</td>', 'Lovely - is there a candle inside? That''s how it looks. Very nice.', '2004-08-16 17:01:53.000000', NULL, 1),
(861946, 97428, 3087, '<td valign="top">Lovely sweeping curves and black and white really focuses viewer on the lines, light, shadow and textures. Nice low DOF coming straight at me in the corner.</td>', 'Lovely sweeping curves and black and white really focuses viewer on the lines, light, shadow and textures. Nice low DOF coming straight at me in the corner.', '2004-08-16 17:02:45.000000', NULL, 1),
(861948, 97891, 3087, '<td valign="top">Beautifuk composition. I do like droplets on leaves shots but sometimes they can be a bit samey. I love how this one is more abstract and is all about that double waved edge of leaf and the almost perfect sphere of the droplet. That''s just beautiful to me and composition very strong.</td>', 'Beautifuk composition. I do like droplets on leaves shots but sometimes they can be a bit samey. I love how this one is more abstract and is all about that double waved edge of leaf and the almost perfect sphere of the droplet. That''s just beautiful to me and composition very strong.', '2004-08-16 17:05:20.000000', NULL, 1),
(861949, 97448, 3087, '<td valign="top">Ooooooooooh nice abstract with strong sense of golden light.</td>', 'Ooooooooooh nice abstract with strong sense of golden light.', '2004-08-16 17:06:01.000000', NULL, 1),
(861951, 97763, 3087, '<td valign="top">Nice use of lens to show examination of flora (botany) not just flora itself but don''t like selective desat here.</td>', 'Nice use of lens to show examination of flora (botany) not just flora itself but don''t like selective desat here.', '2004-08-16 17:07:00.000000', NULL, 1),
(861953, 97088, 19959, '<td valign="top">Excellent detail.</td>', 'Excellent detail.', '2004-08-16 17:07:34.000000', NULL, 1),
(861955, 96652, 8139, '<td valign="top">The Zen touch...................................... Oh well.........10 !</td>', 'The Zen touch...................................... Oh well.........10 !', '2004-08-16 17:09:34.000000', NULL, 1),
(861958, 97347, 19959, '<td valign="top">Excellent diagonal composition. Top 3 entry IMO</td>', 'Excellent diagonal composition. Top 3 entry IMO', '2004-08-16 17:10:06.000000', NULL, 1),
(861959, 97558, 8139, '<td valign="top">Nice lesson...</td>', 'Nice lesson...', '2004-08-16 17:11:35.000000', NULL, 1),
(861961, 97992, 19959, '<td valign="top">The truck in the background is distracting.</td>', 'The truck in the background is distracting.', '2004-08-16 17:12:31.000000', NULL, 1),
(861964, 97309, 24642, '<td valign="top">Geat title.  Good shot.</td>', 'Geat title.  Good shot.', '2004-08-16 17:14:06.000000', NULL, 1),
(861965, 96896, 19978, '<td valign="top">Technically very nice and artistically pleasing. Love the soft background.</td>', 'Technically very nice and artistically pleasing. Love the soft background.', '2004-08-16 17:14:56.000000', NULL, 1),
(861967, 97982, 3087, '<td valign="top">Absolutely beautiful backlighting and love the use of back one to add depth and softness. Love the graduated and dappled nature of the background too.</td>', 'Absolutely beautiful backlighting and love the use of back one to add depth and softness. Love the graduated and dappled nature of the background too.', '2004-08-16 17:15:09.000000', NULL, 1),
(861968, 97190, 3087, '<td valign="top">Nice abstract, I really like it.</td>', 'Nice abstract, I really like it.', '2004-08-16 17:15:42.000000', NULL, 1),
(861969, 97515, 19978, '<td valign="top">Outstanding play of light and shadow. The lack of a clear focal point may hinder you some but I think it is a striking image. Nicely done!</td>', 'Outstanding play of light and shadow. The lack of a clear focal point may hinder you some but I think it is a striking image. Nicely done!', '2004-08-16 17:16:07.000000', NULL, 1),
(861970, 97331, 3087, '<td valign="top">Striking!</td>', 'Striking!', '2004-08-16 17:16:08.000000', NULL, 1),
(861972, 97333, 24642, '<td valign="top">Good title.</td>', 'Good title.', '2004-08-16 17:17:46.000000', NULL, 1),
(861973, 97799, 19978, '<td valign="top">Beautiful. When the page first came up on my monitor, the bottom leaf was excluded due to the portrait crop and my attention was captured by the middle leaf on the right (deep shadow relief). It was some time before I realized I wasn''t seeing the full image and scrolled down. Though it''s a lovely composition, I almost think it would have been stronger with more negative space (the black background is extremely strong!). All in all, a beautiful photograph and one very worthy of a high finish!</td>', 'Beautiful. When the page first came up on my monitor, the bottom leaf was excluded due to the portrait crop and my attention was captured by the middle leaf on the right (deep shadow relief). It was some time before I realized I wasn''t seeing the full image and scrolled down. Though it''s a lovely composition, I almost think it would have been stronger with more negative space (the black background is extremely strong!). All in all, a beautiful photograph and one very worthy of a high finish!', '2004-08-16 17:19:07.000000', NULL, 1),
(861974, 97442, 24642, '<td valign="top">What a refreshing change from the traditional flower shots.  Beutiful abstract shapes.  Very nice balance in form and color.</td>', 'What a refreshing change from the traditional flower shots.  Beutiful abstract shapes.  Very nice balance in form and color.', '2004-08-16 17:20:14.000000', NULL, 1),
(861976, 97347, 8139, '<td valign="top">One of the bests of this kind. (better as mine :) Nice composition, and the blurred one in the background is a plus... great backlighting. ... 10</td>', 'One of the bests of this kind. (better as mine :) Nice composition, and the blurred one in the background is a plus... great backlighting. ... 10', '2004-08-16 17:22:15.000000', NULL, 1),
(861977, 97297, 19978, '<td valign="top">Absolutely lovely composition and crop. Stunning. My hat is off to you.</td>', 'Absolutely lovely composition and crop. Stunning. My hat is off to you.', '2004-08-16 17:22:38.000000', NULL, 1),
(861978, 97041, 19978, '<td valign="top">Beautiful. A shot full of emotion and expression. The soft colors are lovely and your choice of viewing angle creates an illusion of fire or flame. Simply gorgeous.</td>', 'Beautiful. A shot full of emotion and expression. The soft colors are lovely and your choice of viewing angle creates an illusion of fire or flame. Simply gorgeous.', '2004-08-16 17:24:13.000000', NULL, 1),
(861979, 97944, 19978, '<td valign="top">Outstanding eye and imagination for finding a shot like this. Very beautiful.</td>', 'Outstanding eye and imagination for finding a shot like this. Very beautiful.', '2004-08-16 17:24:44.000000', NULL, 1),
(861982, 97992, 19978, '<td valign="top">The background truck must have been intentional but I don''t see the point. It looks as though you had an overcast day and I think a brilliant blue sky for the background would have been better, but maybe you never got the chance. As it is, I think the flowers lose their impact by the busy background. Great focus and sharpness on the plants themselves.</td>', 'The background truck must have been intentional but I don''t see the point. It looks as though you had an overcast day and I think a brilliant blue sky for the background would have been better, but maybe you never got the chance. As it is, I think the flowers lose their impact by the busy background. Great focus and sharpness on the plants themselves.', '2004-08-16 17:27:30.000000', NULL, 1),
(861984, 97558, 24642, '<td valign="top">Nice idea and a good title.</td>', 'Nice idea and a good title.', '2004-08-16 17:27:45.000000', NULL, 1),
(861986, 97973, 19978, '<td valign="top">A beautiful flower - I don''t think I''ve ever seen one. The simple composition works well. I like the square crop.</td>', 'A beautiful flower - I don''t think I''ve ever seen one. The simple composition works well. I like the square crop.', '2004-08-16 17:28:26.000000', NULL, 1),
(861988, 97177, 19978, '<td valign="top">A lot of effort, clearly. Nice imagination and composition. Good creative response to the challenge.</td>', 'A lot of effort, clearly. Nice imagination and composition. Good creative response to the challenge.', '2004-08-16 17:29:26.000000', NULL, 1),
(861994, 97984, 19978, '<td valign="top">An absolutely beautiful flower, but my mind''s eye wants to see this against a black background. It would make the red really pop and the brownish anthers would still be very strong. As it is, the background is too busy for me and distracts away from the central subject.</td>', 'An absolutely beautiful flower, but my mind''s eye wants to see this against a black background. It would make the red really pop and the brownish anthers would still be very strong. As it is, the background is too busy for me and distracts away from the central subject.', '2004-08-16 17:32:00.000000', NULL, 1),
(861995, 97802, 24642, '<td valign="top">Good use of DOF.</td>', 'Good use of DOF.', '2004-08-16 17:32:29.000000', NULL, 1),
(861997, 97700, 19978, '<td valign="top">Beautiful shot. I found some of these too, but in the end couldn''t get one good enough to submit. Excellent crop and composition too. Very nice!</td>', 'Beautiful shot. I found some of these too, but in the end couldn''t get one good enough to submit. Excellent crop and composition too. Very nice!', '2004-08-16 17:34:43.000000', NULL, 1),
(861998, 97782, 19978, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2004-08-16 17:34:54.000000', NULL, 1),
(862001, 97428, 23312, '<td valign="top">Nice DOF and texture on the petals - but the B&amp;W doesn''t work for me, I''d like to see this in full color.</td>', 'Nice DOF and texture on the petals - but the B&W doesn''t work for me, I''d like to see this in full color.', '2004-08-16 17:37:18.000000', NULL, 1),
(862006, 97783, 23312, '<td valign="top">Interesting approach - I like it!</td>', 'Interesting approach - I like it!', '2004-08-16 17:39:53.000000', NULL, 1),
(862024, 97350, 25529, '<td valign="top">good one</td>', 'good one', '2004-08-16 17:53:26.000000', NULL, 1),
(862029, 97832, 23312, '<td valign="top">I like showing the flowers and the buds - gives a good "botanical" feel, but I don''t think the black background works for this shot.</td>', 'I like showing the flowers and the buds - gives a good "botanical" feel, but I don''t think the black background works for this shot.', '2004-08-16 17:57:09.000000', NULL, 1),
(862031, 96652, 13365, '<td valign="top">Love the simplicity and mood that the image conveys. The Huge white border was a poor choice as it is a bit overwhelming for such a nice photo.  8</td>', 'Love the simplicity and mood that the image conveys. The Huge white border was a poor choice as it is a bit overwhelming for such a nice photo.  8', '2004-08-16 17:59:42.000000', NULL, 1),
(862033, 97558, 21217, '<td valign="top">My favourite in this challenge. I hope you win.</td>', 'My favourite in this challenge. I hope you win.', '2004-08-16 18:03:08.000000', NULL, 1),
(862037, 97442, 21217, '<td valign="top">Perfect color, light, composition and sharpness. I hope you win a ribbon.</td>', 'Perfect color, light, composition and sharpness. I hope you win a ribbon.', '2004-08-16 18:04:31.000000', NULL, 1),
(862041, 97994, 11793, '<td valign="top">nice crisp shot of the bees - i think the BG being a bit more blurred would help this a bit.<br/> <br/>good luck</td>', 'nice crisp shot of the bees - i think the BG being a bit more blurred would help this a bit. good luck', '2004-08-16 18:06:08.000000', NULL, 1),
(862042, 97347, 23312, '<td valign="top">Very nice - I really like the one in the background - that takes an already good shot to the next level.</td>', 'Very nice - I really like the one in the background - that takes an already good shot to the next level.', '2004-08-16 18:06:34.000000', NULL, 1),
(862043, 97802, 21217, '<td valign="top">Simply perfect. I hope you win a ribbon.</td>', 'Simply perfect. I hope you win a ribbon.', '2004-08-16 18:07:02.000000', NULL, 1),
(862045, 97875, 11793, '<td valign="top">not sure the plant life plays a central role in this image.<br/> <br/>the way the lines all are crooked is a bit distracting.</td>', 'not sure the plant life plays a central role in this image. the way the lines all are crooked is a bit distracting.', '2004-08-16 18:07:53.000000', NULL, 1),
(862047, 97041, 21217, '<td valign="top">Like a candel.... perfect shot. I hope you win a ribbon</td>', 'Like a candel.... perfect shot. I hope you win a ribbon', '2004-08-16 18:08:56.000000', NULL, 1),
(862048, 98016, 20375, '<td valign="top">Wow. I''m hoping for a top ten finish on my entry and it''s entries like this that blow me away. Excellent excellent shot - 9.<br/>Good focus, good dof and.....good feeling when you ribbon!</td>', 'Wow. I''m hoping for a top ten finish on my entry and it''s entries like this that blow me away. Excellent excellent shot - 9.Good focus, good dof and.....good feeling when you ribbon!', '2004-08-16 18:09:05.000000', NULL, 1),
(862050, 97442, 11793, '<td valign="top">ahh - so that''s a money tree - i''ll keep my eyes open for one now.<br/> <br/>interesting angle - good luck</td>', 'ahh - so that''s a money tree - i''ll keep my eyes open for one now. interesting angle - good luck', '2004-08-16 18:10:34.000000', NULL, 1),
(862051, 96652, 20375, '<td valign="top">Whew! I almost did the same kind of shot before picking another plant!<br/>Simplicity is what makes this shot so beautiful. Simplicity and, composition, lighting, focus,  correct exposure ... you nailed it. Excellent image.</td>', 'Whew! I almost did the same kind of shot before picking another plant!Simplicity is what makes this shot so beautiful. Simplicity and, composition, lighting, focus,  correct exposure ... you nailed it. Excellent image.', '2004-08-16 18:10:39.000000', NULL, 1),
(862055, 97190, 20375, '<td valign="top">Wow. Talk about going outside the box!. I admire your adventuresome spirit!<br/>Excellent composition. I can look at this and SEE wind! <br/>Colour is awesome, captured motion wonderfully. Nice to look at.<br/>Top ten easy if not a ribbon!</td>', 'Wow. Talk about going outside the box!. I admire your adventuresome spirit!Excellent composition. I can look at this and SEE wind! Colour is awesome, captured motion wonderfully. Nice to look at.Top ten easy if not a ribbon!', '2004-08-16 18:13:15.000000', NULL, 1),
(862056, 96797, 20375, '<td valign="top">The lighting on this is very dramatic. Very nice shot. Top ten!</td>', 'The lighting on this is very dramatic. Very nice shot. Top ten!', '2004-08-16 18:13:47.000000', NULL, 1),
(862062, 97975, 19608, '<td valign="top">Superb submission.  I love the three darker (orange) petals mixed in with the yellow.  If you didn''t stop all the way down, try it to get the upper green leaf sharper.  Black background is great.</td>', 'Superb submission.  I love the three darker (orange) petals mixed in with the yellow.  If you didn''t stop all the way down, try it to get the upper green leaf sharper.  Black background is great.', '2004-08-16 18:19:15.000000', NULL, 1),
(862064, 97781, 14476, '<td valign="top">Very much like your play of shadows on this leaf.  I would suggest that it is just a tiny touch too dark, though.  (Yes, my monitor is calibrated)  Still, it''s an exciting image and you showed good imagination to bring out  the beauty in the veins.</td>', 'Very much like your play of shadows on this leaf.  I would suggest that it is just a tiny touch too dark, though.  (Yes, my monitor is calibrated)  Still, it''s an exciting image and you showed good imagination to bring out  the beauty in the veins.', '2004-08-16 18:20:18.000000', NULL, 1),
(862071, 97655, 6520, '<td valign="top">looks like a crocks eye well done 8</td>', 'looks like a crocks eye well done 8', '2004-08-16 18:22:48.000000', NULL, 1),
(862098, 97937, 14476, '<td valign="top">Good image with elegant colors, shadings.  The water is shadowed/illuminated to provide a pefect foil for the green shapes.  The partial leaves at the top of the image are just a bit distracting; still a very, very good entry.  8</td>', 'Good image with elegant colors, shadings.  The water is shadowed/illuminated to provide a pefect foil for the green shapes.  The partial leaves at the top of the image are just a bit distracting; still a very, very good entry.  8', '2004-08-16 18:38:23.000000', NULL, 1),
(862103, 96797, 14476, '<td valign="top">The mood created by the lighting and colors makes this image an outstanding one.  It''s well done art and goes into my favorites now.  10</td>', 'The mood created by the lighting and colors makes this image an outstanding one.  It''s well done art and goes into my favorites now.  10', '2004-08-16 18:40:48.000000', NULL, 1),
(862105, 97953, 14476, '<td valign="top">Colors are perfect for this treatment of the flower.  If it was mine, I''d probably do a tighter crop left and right, but still, the mood you have created for this is a joy.  8</td>', 'Colors are perfect for this treatment of the flower.  If it was mine, I''d probably do a tighter crop left and right, but still, the mood you have created for this is a joy.  8', '2004-08-16 18:42:20.000000', NULL, 1),
(862106, 98017, 14476, '<td valign="top">Good use of complimentary colors and lighting to bring out the beauty of this bromeliad.      Nicely done.  8</td>', 'Good use of complimentary colors and lighting to bring out the beauty of this bromeliad.      Nicely done.  8', '2004-08-16 18:44:05.000000', NULL, 1),
(862112, 97828, 3032, '<td valign="top">It looks like winter and spring in one, works well. Good composition.</td>', 'It looks like winter and spring in one, works well. Good composition.', '2004-08-16 18:50:06.000000', NULL, 1),
(862117, 97992, 10390, '<td valign="top">The background ruins this photo, you should have placed the camera lower, pointing it upwards so the photo would be more simple with "clean" background, better luck next time!</td>', 'The background ruins this photo, you should have placed the camera lower, pointing it upwards so the photo would be more simple with "clean" background, better luck next time!', '2004-08-16 18:55:22.000000', NULL, 1),
(862125, 97190, 10390, '<td valign="top">Good colors, abstract, I like it a lot!  Maybe you''ll get many low ratings, but that''s just the variable tastes of people, sorry.  But on the other hand, if there are some people here, liking it as much as me, then I think this could be just above midrange.</td>', 'Good colors, abstract, I like it a lot!  Maybe you''ll get many low ratings, but that''s just the variable tastes of people, sorry.  But on the other hand, if there are some people here, liking it as much as me, then I think this could be just above midrange.', '2004-08-16 18:59:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(862152, 97828, 12268, '<td valign="top">great use of ir here. I really like this shot!</td>', 'great use of ir here. I really like this shot!', '2004-08-16 19:22:01.000000', NULL, 1),
(862167, 97812, 19608, '<td valign="top">Excellent study in shapes and textures.  The patterns in the leaves are crisp and fun.  The black background works great but makes it feel like the leaves are just "floating in space" - not cecessarily a bad thing.  The title lacks imagination...</td>', 'Excellent study in shapes and textures.  The patterns in the leaves are crisp and fun.  The black background works great but makes it feel like the leaves are just "floating in space" - not cecessarily a bad thing.  The title lacks imagination...', '2004-08-16 19:32:37.000000', NULL, 1),
(862168, 97829, 19608, '<td valign="top">Lighting, composition, exposure, focus are all superb.  Wow factor is really close.  Title is pretty scientific sounding.</td>', 'Lighting, composition, exposure, focus are all superb.  Wow factor is really close.  Title is pretty scientific sounding.', '2004-08-16 19:34:47.000000', NULL, 1),
(862170, 96914, 25143, '<td valign="top">very dramatic - I like the slightly off-center angle</td>', 'very dramatic - I like the slightly off-center angle', '2004-08-16 19:36:22.000000', NULL, 1),
(862171, 97921, 19608, '<td valign="top">Nice colors and sihlouettes. It meets the challenge ok - but is not filled with a lot of Botany impact.</td>', 'Nice colors and sihlouettes. It meets the challenge ok - but is not filled with a lot of Botany impact.', '2004-08-16 19:36:28.000000', NULL, 1),
