(862527, 96655, 24546, '<td valign="top">This is a lovely, peaceful place. I like the fog.</td>', 'This is a lovely, peaceful place. I like the fog.', '2004-08-16 23:46:01.000000', NULL, 1),
(862529, 97447, 24546, '<td valign="top">WOW!  This is exquisite!  Love the detail throughout the flower - nice and sharp - as are all the water drops!  Great job!</td>', 'WOW!  This is exquisite!  Love the detail throughout the flower - nice and sharp - as are all the water drops!  Great job!', '2004-08-16 23:48:07.000000', NULL, 1),
(862531, 97706, 24546, '<td valign="top">I love the delicate lacy look of the vein lines on the upper left!  Great detail throughout the picture and so much for the eye to explore!</td>', 'I love the delicate lacy look of the vein lines on the upper left!  Great detail throughout the picture and so much for the eye to explore!', '2004-08-16 23:49:14.000000', NULL, 1),
(862533, 97167, 24546, '<td valign="top">I like how sharp this image is. Your eye is definitely drawn to the red center! Nice job!</td>', 'I like how sharp this image is. Your eye is definitely drawn to the red center! Nice job!', '2004-08-16 23:51:59.000000', NULL, 1),
(862535, 96723, 24546, '<td valign="top">What a fun sense of humor!! Love the composition!</td>', 'What a fun sense of humor!! Love the composition!', '2004-08-16 23:52:37.000000', NULL, 1),
(862537, 96797, 24546, '<td valign="top">Love your lighting here - how it is dark at the top and gradually increases to get to the bright light at the base!  I love how the vase and the plant sit in the frame. This one is really nice.</td>', 'Love your lighting here - how it is dark at the top and gradually increases to get to the bright light at the base!  I love how the vase and the plant sit in the frame. This one is really nice.', '2004-08-16 23:55:51.000000', NULL, 1),
(862539, 97309, 24546, '<td valign="top">Whee! Three at a time!  Love the vibrant colors.</td>', 'Whee! Three at a time!  Love the vibrant colors.', '2004-08-16 23:57:14.000000', NULL, 1),
(862541, 97526, 24546, '<td valign="top">Love your choice of depth of field here. Love the colors in the bloom and the detail throughout the plant!</td>', 'Love your choice of depth of field here. Love the colors in the bloom and the detail throughout the plant!', '2004-08-16 23:58:27.000000', NULL, 1),
(862543, 97966, 24546, '<td valign="top">This is gorgeous!  It works so well as a black and white!  You have great detail throughout!  And the lighting is wonderful!  Great job!</td>', 'This is gorgeous!  It works so well as a black and white!  You have great detail throughout!  And the lighting is wonderful!  Great job!', '2004-08-17 00:00:38.000000', NULL, 1),
(862546, 97883, 24546, '<td valign="top">Love how your flower shows up against that bright blue!  Great job in capturing the details!</td>', 'Love how your flower shows up against that bright blue!  Great job in capturing the details!', '2004-08-17 00:03:09.000000', NULL, 1),
(862549, 97942, 24546, '<td valign="top">OOHHH! This one is really cool!  I like your concept and you executed it well!  Very nice job!</td>', 'OOHHH! This one is really cool!  I like your concept and you executed it well!  Very nice job!', '2004-08-17 00:04:41.000000', NULL, 1),
