(862555, 97652, 24546, '<td valign="top">Very creative!  I love it!</td>', 'Very creative!  I love it!', '2004-08-17 00:11:40.000000', NULL, 1),
(862556, 97428, 24546, '<td valign="top">Beautiful!  I love it!</td>', 'Beautiful!  I love it!', '2004-08-17 00:13:59.000000', NULL, 1),
(862561, 98016, 24546, '<td valign="top">WOW!  This is beautiful!  love how you captured both the details in the water lily as well as the lily pads.  Great placement!  And your lighting is superb!  Great job!</td>', 'WOW!  This is beautiful!  love how you captured both the details in the water lily as well as the lily pads.  Great placement!  And your lighting is superb!  Great job!', '2004-08-17 00:17:36.000000', NULL, 1),
(862563, 97088, 24546, '<td valign="top">This is lovely! Love how you captured the details throughout the flower and how sharp the water drops are!  It looks great as black and white. Great job!</td>', 'This is lovely! Love how you captured the details throughout the flower and how sharp the water drops are!  It looks great as black and white. Great job!', '2004-08-17 00:22:09.000000', NULL, 1),
(862564, 97732, 24546, '<td valign="top">Great idea that made a great still life!</td>', 'Great idea that made a great still life!', '2004-08-17 00:22:49.000000', NULL, 1),
(862566, 97797, 24546, '<td valign="top">What wonderful detail in the delicate flowers!  Great job!</td>', 'What wonderful detail in the delicate flowers!  Great job!', '2004-08-17 00:23:45.000000', NULL, 1),
(862568, 97944, 24546, '<td valign="top">This is truly lovely!  The center almost looks like a tiger!  Definitely an eye catcher!</td>', 'This is truly lovely!  The center almost looks like a tiger!  Definitely an eye catcher!', '2004-08-17 00:25:50.000000', NULL, 1),
(862570, 97515, 24546, '<td valign="top">WOW! Your lighting here makes the leaves glow!  And you still hve the details!  Nice job!</td>', 'WOW! Your lighting here makes the leaves glow!  And you still hve the details!  Nice job!', '2004-08-17 00:27:15.000000', NULL, 1),
(862575, 97902, 24546, '<td valign="top">Very elegant!  Love the rich colors!</td>', 'Very elegant!  Love the rich colors!', '2004-08-17 00:30:45.000000', NULL, 1),
(862578, 97843, 24546, '<td valign="top">Amazing how these plants grow in the desert sands!  Beautiful shot!</td>', 'Amazing how these plants grow in the desert sands!  Beautiful shot!', '2004-08-17 00:33:43.000000', NULL, 1),
(862579, 97558, 24546, '<td valign="top">Beauty through simplicity!  This one is great! Love the progression of colors!  Great job!</td>', 'Beauty through simplicity!  This one is great! Love the progression of colors!  Great job!', '2004-08-17 00:34:38.000000', NULL, 1),
(862581, 97975, 24546, '<td valign="top">Beautiful detail in this flower!  Love it!</td>', 'Beautiful detail in this flower!  Love it!', '2004-08-17 00:36:26.000000', NULL, 1),
(862588, 98017, 24546, '<td valign="top">Love the rich colors and the use of line here!  So nice and sharp! Lovely!</td>', 'Love the rich colors and the use of line here!  So nice and sharp! Lovely!', '2004-08-17 00:38:45.000000', NULL, 1),
(862594, 97953, 24546, '<td valign="top">I love your lighting on this one. I also like the contrast between the blues and the glowing center.</td>', 'I love your lighting on this one. I also like the contrast between the blues and the glowing center.', '2004-08-17 00:47:13.000000', NULL, 1),
(862637, 97671, 25464, '<td valign="top">This is a gorgeous photograph and I have given it a high score; however, I feel someone judging this photo would have to say it technically meets the challenge as a botany photograph because it has flowers rather than seeing botany as the central theme of the photo.</td>', 'This is a gorgeous photograph and I have given it a high score; however, I feel someone judging this photo would have to say it technically meets the challenge as a botany photograph because it has flowers rather than seeing botany as the central theme of the photo.', '2004-08-17 01:13:26.000000', NULL, 1),
(862639, 97528, 25464, '<td valign="top">Soothing, elegant, beautiful work.<br/></td>', 'Soothing, elegant, beautiful work.', '2004-08-17 01:14:26.000000', NULL, 1),
(862640, 97041, 25464, '<td valign="top">Stunning.  A+</td>', 'Stunning.  A+', '2004-08-17 01:14:52.000000', NULL, 1),
(862641, 97843, 25464, '<td valign="top">Exceptional.  Who knew weeds could be so nice.</td>', 'Exceptional.  Who knew weeds could be so nice.', '2004-08-17 01:15:37.000000', NULL, 1),
(862720, 97631, 12253, '<td valign="top">A pretty shot, but I think the crop in the front is too severe, missing the left of the front flower.</td>', 'A pretty shot, but I think the crop in the front is too severe, missing the left of the front flower.', '2004-08-17 02:51:02.000000', NULL, 1),
(862722, 97528, 12253, '<td valign="top">I like the composition and subject very much; it would be better if the focus were on the more central stamen--the one on the bottom right is very sharp, but it''s not prominent in the image.</td>', 'I like the composition and subject very much; it would be better if the focus were on the more central stamen--the one on the bottom right is very sharp, but it''s not prominent in the image.', '2004-08-17 02:53:37.000000', NULL, 1),
