(862777, 97968, 6172, '<td valign="top">seems to be nothing much to focus my attention on here</td>', 'seems to be nothing much to focus my attention on here', '2004-08-17 05:12:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(862779, 97830, 6172, '<td valign="top">nice laid back scene</td>', 'nice laid back scene', '2004-08-17 05:16:30.000000', NULL, 1),
(862784, 97652, 10433, '<td valign="top">would looks better with her red eyes...  :)</td>', 'would looks better with her red eyes...  :)', '2004-08-17 05:24:28.000000', NULL, 1),
(862795, 97723, 6172, '<td valign="top">this seems so cluttered that I can hardly make out what it is.</td>', 'this seems so cluttered that I can hardly make out what it is.', '2004-08-17 05:31:57.000000', NULL, 1),
(862798, 97285, 6172, '<td valign="top">doesn''t seem very effective in b&amp;w to me</td>', 'doesn''t seem very effective in b&w to me', '2004-08-17 05:35:17.000000', NULL, 1),
(862803, 97542, 6172, '<td valign="top">great simplicity, nice colors</td>', 'great simplicity, nice colors', '2004-08-17 05:52:25.000000', NULL, 1),
(862807, 97671, 6172, '<td valign="top">"Dreamy",  I expect you to ribbon :)</td>', '"Dreamy",  I expect you to ribbon :)', '2004-08-17 06:00:07.000000', NULL, 1),
(862808, 97551, 6172, '<td valign="top">Very nice and colorful</td>', 'Very nice and colorful', '2004-08-17 06:01:32.000000', NULL, 1),
(862824, 97520, 10390, '<td valign="top">Good photo, would be better and even have a chance for a ribbon if you crop the leaf at the bottom in the background from the photo, leaving you with a square format photo.  I like the colors and lighting condition.</td>', 'Good photo, would be better and even have a chance for a ribbon if you crop the leaf at the bottom in the background from the photo, leaving you with a square format photo.  I like the colors and lighting condition.', '2004-08-17 07:02:35.000000', NULL, 1),
(862839, 97789, 3087, '<td valign="top">I like your effort to show that botany is about the STUDY of flora and isn''t just a synonym for the word flora. Composition is nice but contrast and tonal range seem very low - there are no actual whites in this image. Am wondering whether choice of black and white has improved or weakened this shot.</td>', 'I like your effort to show that botany is about the STUDY of flora and isn''t just a synonym for the word flora. Composition is nice but contrast and tonal range seem very low - there are no actual whites in this image. Am wondering whether choice of black and white has improved or weakened this shot.', '2004-08-17 08:12:54.000000', NULL, 1),
(862841, 97010, 21430, '<td valign="top">This is a nice capture, but it is really flat colorwise and doesn''t grab attention because of that. I am unsure how you would make this more vibrant, perhaps at a different time of day or with a different light source, some more of the pink and green could be brought out.</td>', 'This is a nice capture, but it is really flat colorwise and doesn''t grab attention because of that. I am unsure how you would make this more vibrant, perhaps at a different time of day or with a different light source, some more of the pink and green could be brought out.', '2004-08-17 08:16:44.000000', NULL, 1),
(862862, 97297, 14614, '<td valign="top">The misty background trees move this from plain to interesting, good eye</td>', 'The misty background trees move this from plain to interesting, good eye', '2004-08-17 08:55:59.000000', NULL, 1),
(862865, 97980, 14614, '<td valign="top">what works in your somewhat quirky shot is the composition -- leading lines from knee to the botony pay-off and the interesing blend of colors. bol.</td>', 'what works in your somewhat quirky shot is the composition -- leading lines from knee to the botony pay-off and the interesing blend of colors. bol.', '2004-08-17 08:58:38.000000', NULL, 1),
(862866, 97643, 14614, '<td valign="top">back ground blue is just right, nicelly done composition</td>', 'back ground blue is just right, nicelly done composition', '2004-08-17 08:59:19.000000', NULL, 1),
(862868, 98023, 14614, '<td valign="top">you got the lighting just right - BOL</td>', 'you got the lighting just right - BOL', '2004-08-17 09:00:43.000000', NULL, 1),
(862870, 97955, 14614, '<td valign="top">excellent composition for this unusual botony shot</td>', 'excellent composition for this unusual botony shot', '2004-08-17 09:02:54.000000', NULL, 1),
(862872, 98019, 14614, '<td valign="top">in your composition the botony takes a back seat to the structure as I view it</td>', 'in your composition the botony takes a back seat to the structure as I view it', '2004-08-17 09:03:34.000000', NULL, 1),
(862874, 97988, 14614, '<td valign="top">(you and I have similar subjects)  you''ve done a wonderful job with the composition.  bol</td>', '(you and I have similar subjects)  you''ve done a wonderful job with the composition.  bol', '2004-08-17 09:05:35.000000', NULL, 1),
(862877, 97950, 14614, '<td valign="top">you have nailed the shot for the traditional botony study - very well done.</td>', 'you have nailed the shot for the traditional botony study - very well done.', '2004-08-17 09:07:07.000000', NULL, 1),
(862878, 97843, 21430, '<td valign="top">Very nice capture. The main thing that I would change is to crop/tilt the image slightly to overcome the very slight horizon issue. There are a considerable number of people that will mark down for the minor tweak you have in your horizon here.<br/> <br/>  The only other thing that I would do is play with some of individual color saturation levels to bring out a little more of the blues, yellows and perhaps the greens as well.</td>', 'Very nice capture. The main thing that I would change is to crop/tilt the image slightly to overcome the very slight horizon issue. There are a considerable number of people that will mark down for the minor tweak you have in your horizon here.   The only other thing that I would do is play with some of individual color saturation levels to bring out a little more of the blues, yellows and perhaps the greens as well.', '2004-08-17 09:07:29.000000', NULL, 1),
(862881, 97330, 14614, '<td valign="top">i find the yellow background distracts me from your excellently composed  foreground</td>', 'i find the yellow background distracts me from your excellently composed  foreground', '2004-08-17 09:09:43.000000', NULL, 1),
(862883, 97769, 14614, '<td valign="top">your colors work well to set a mood here, i would like a bit more crispness in the large right leaf... bol</td>', 'your colors work well to set a mood here, i would like a bit more crispness in the large right leaf... bol', '2004-08-17 09:10:33.000000', NULL, 1),
(862885, 97918, 21430, '<td valign="top">This is a very nice landscape shot. I really like the vibrant capture of color between the blues and the greens here.  The only issue with this image is that it doesn''t completely meet the challenge. I am unsure which plant life is the main focus of this image. <br/> <br/>  Is it what appears to be a small stand of trees to the right of the image? Is it the ''stump/roots'' collection in the middle right of the image? Is it the grasses that are all over the scene?<br/> <br/>  I would score this higher with a clearly defined focus on a particular plant life.</td>', 'This is a very nice landscape shot. I really like the vibrant capture of color between the blues and the greens here.  The only issue with this image is that it doesn''t completely meet the challenge. I am unsure which plant life is the main focus of this image.    Is it what appears to be a small stand of trees to the right of the image? Is it the ''stump/roots'' collection in the middle right of the image? Is it the grasses that are all over the scene?   I would score this higher with a clearly defined focus on a particular plant life.', '2004-08-17 09:11:04.000000', NULL, 1),
(862886, 97875, 14614, '<td valign="top">lovely colors, interesting choice of subjects, would like the flowers to be more of a main element ONLY because of the challenge theme - as a stand alone shot you have a fine one</td>', 'lovely colors, interesting choice of subjects, would like the flowers to be more of a main element ONLY because of the challenge theme - as a stand alone shot you have a fine one', '2004-08-17 09:12:34.000000', NULL, 1),
(862887, 97979, 21430, '<td valign="top">This image is really flat. It''s not very colorful and vibrant. If you play with some of the color saturation it could be brought more to life. <br/> <br/>   Other then that there isn''t a real strong focus on plant life so much as on the dead wooden fence. That''s where I keep finding my eyes drawn to as it stands out from everything around it.</td>', 'This image is really flat. It''s not very colorful and vibrant. If you play with some of the color saturation it could be brought more to life.     Other then that there isn''t a real strong focus on plant life so much as on the dead wooden fence. That''s where I keep finding my eyes drawn to as it stands out from everything around it.', '2004-08-17 09:13:38.000000', NULL, 1),
(862902, 96723, 25150, '<td valign="top">cute,<br/> <br/>doesn''t say "botany'' to me though, maybe another contest entry?<br/> <br/>After careful consideration, I''ve decided I love this photo. It''s very funny, so I''m bumping you up a few notches. Keep up the great shots!</td>', 'cute, doesn''t say "botany'' to me though, maybe another contest entry? After careful consideration, I''ve decided I love this photo. It''s very funny, so I''m bumping you up a few notches. Keep up the great shots!', '2004-08-17 09:33:34.000000', NULL, 1),
(862905, 97915, 5822, '<td valign="top">A little bit too much reflection off of the apple.  A polarizer or ND filter would improve this shot.</td>', 'A little bit too much reflection off of the apple.  A polarizer or ND filter would improve this shot.', '2004-08-17 09:35:39.000000', NULL, 1),
(862920, 97750, 5822, '<td valign="top">Great color saturation and brightness and focus is very crisp. I also like the negative space which adds so much richness to this image.</td>', 'Great color saturation and brightness and focus is very crisp. I also like the negative space which adds so much richness to this image.', '2004-08-17 09:50:33.000000', NULL, 1),
(862922, 97526, 5728, '<td valign="top">One of the 4 tens I have given this time around. Fantastic image!</td>', 'One of the 4 tens I have given this time around. Fantastic image!', '2004-08-17 09:54:22.000000', NULL, 1),
(862923, 96723, 5728, '<td valign="top">Clever idea (10).</td>', 'Clever idea (10).', '2004-08-17 09:54:36.000000', NULL, 1),
(862924, 97551, 5728, '<td valign="top">A perfect 10 from me :)</td>', 'A perfect 10 from me :)', '2004-08-17 09:54:53.000000', NULL, 1),
(862925, 97929, 5728, '<td valign="top">Amazing shot! The last of the 4 tens I have given for this challenge!</td>', 'Amazing shot! The last of the 4 tens I have given for this challenge!', '2004-08-17 09:55:36.000000', NULL, 1),
(862927, 97722, 5822, '<td valign="top">Wonderful close up with lots of fine detail, crisp sharpness and good DOF. Color is a bit muted, but still very nice.</td>', 'Wonderful close up with lots of fine detail, crisp sharpness and good DOF. Color is a bit muted, but still very nice.', '2004-08-17 09:56:00.000000', NULL, 1),
(862928, 97763, 5728, '<td valign="top">Clever idea, well pulled off (9).</td>', 'Clever idea, well pulled off (9).', '2004-08-17 09:56:07.000000', NULL, 1),
(862942, 97088, 5822, '<td valign="top">The tone and texture of this flower is absolutely wonderful. It seems so tangible! The soft lighting is just perfect. Excellent work!</td>', 'The tone and texture of this flower is absolutely wonderful. It seems so tangible! The soft lighting is just perfect. Excellent work!', '2004-08-17 10:06:58.000000', NULL, 1),
(862943, 96723, 14614, '<td valign="top">strong composition and use of light (connection to the theme isn''t as strong as others but in a "general" challenge this would be tops with me) BOL</td>', 'strong composition and use of light (connection to the theme isn''t as strong as others but in a "general" challenge this would be tops with me) BOL', '2004-08-17 10:08:06.000000', NULL, 1),
(862950, 97943, 5822, '<td valign="top">Color is rich and saturated but I think the image could use just a bit more contrast. I also wish your DOF was deeper both near and far so that all of the sunflowers were in focus.</td>', 'Color is rich and saturated but I think the image could use just a bit more contrast. I also wish your DOF was deeper both near and far so that all of the sunflowers were in focus.', '2004-08-17 10:13:55.000000', NULL, 1),
(862964, 97956, 3087, '<td valign="top">Nice choice to go for black and white and I like the dappled rarher than even light. Although shallow DOF throws background out nicely I don''t think it works in terms of the way it throws out the lower left corner of the foreground. There is a good range of tones but perhaps overall too many darker ones?</td>', 'Nice choice to go for black and white and I like the dappled rarher than even light. Although shallow DOF throws background out nicely I don''t think it works in terms of the way it throws out the lower left corner of the foreground. There is a good range of tones but perhaps overall too many darker ones?', '2004-08-17 10:25:43.000000', NULL, 1),
(862974, 97551, 3087, '<td valign="top">Wow this is nice.  I am a sucker for well used shallow DOF though. Lovely vivid colours balanced by dark greens.</td>', 'Wow this is nice.  I am a sucker for well used shallow DOF though. Lovely vivid colours balanced by dark greens.', '2004-08-17 10:37:32.000000', NULL, 1),
(862982, 96797, 15599, '<td valign="top">clever use of light, find the offset image mildly disturbing but interesting... maybe I just like being disturbed.</td>', 'clever use of light, find the offset image mildly disturbing but interesting... maybe I just like being disturbed.', '2004-08-17 10:55:30.000000', NULL, 1),
(862988, 97604, 3895, '<td valign="top">superb</td>', 'superb', '2004-08-17 11:04:07.000000', NULL, 1),
(862989, 97942, 3895, '<td valign="top">i like the color contrasts</td>', 'i like the color contrasts', '2004-08-17 11:04:24.000000', NULL, 1),
(862990, 96896, 3895, '<td valign="top">exceptional</td>', 'exceptional', '2004-08-17 11:04:44.000000', NULL, 1),
(862991, 97011, 3895, '<td valign="top">clear, but not great</td>', 'clear, but not great', '2004-08-17 11:05:25.000000', NULL, 1),
(862992, 97643, 3895, '<td valign="top">big flower</td>', 'big flower', '2004-08-17 11:05:56.000000', NULL, 1),
(863026, 96723, 24494, '<td valign="top">8 from me</td>', '8 from me', '2004-08-17 11:48:43.000000', NULL, 1),
(863029, 97992, 19982, '<td valign="top">There have been lots of sunflower shots in this challenge, and generally I''ve been a sucker for voting high on them.  I do like the flowers here.  Too bad the truck in the background had to cause so much distraction.  Perhaps get down low and shut up high next time so that the sky is in the background instead of the trucks.</td>', 'There have been lots of sunflower shots in this challenge, and generally I''ve been a sucker for voting high on them.  I do like the flowers here.  Too bad the truck in the background had to cause so much distraction.  Perhaps get down low and shut up high next time so that the sky is in the background instead of the trucks.', '2004-08-17 11:49:19.000000', NULL, 1),
(863039, 97655, 23137, '<td valign="top">absolutely stunning, and captivatingly done with a real sense of watchfulness and alertness in the eye.!!  i hope u will consider making a print of this available! :)  a work of mastery indeed!</td>', 'absolutely stunning, and captivatingly done with a real sense of watchfulness and alertness in the eye.!!  i hope u will consider making a print of this available! :)  a work of mastery indeed!', '2004-08-17 11:58:25.000000', NULL, 1),
(863044, 97041, 19982, '<td valign="top">I love it!  The lighting is superb, the details excellent.  I hope you do well!</td>', 'I love it!  The lighting is superb, the details excellent.  I hope you do well!', '2004-08-17 12:02:26.000000', NULL, 1),
(863046, 97801, 19982, '<td valign="top">Great picture.  I love the contrast between the flower and the sky.  The drama behind the flower, yet the obvious sunlight that still lights it.  And the little hanging leaf for some reason just completes the picture.  Hope you do well!</td>', 'Great picture.  I love the contrast between the flower and the sky.  The drama behind the flower, yet the obvious sunlight that still lights it.  And the little hanging leaf for some reason just completes the picture.  Hope you do well!', '2004-08-17 12:03:58.000000', NULL, 1),
(863048, 97811, 19982, '<td valign="top">Love the picture.  Just wish the bees were a little more in focus... same with some of the petals.</td>', 'Love the picture.  Just wish the bees were a little more in focus... same with some of the petals.', '2004-08-17 12:05:29.000000', NULL, 1),
(863072, 97942, 25095, '<td valign="top">There are a couple submitted that have used the magnifying glass idea but you went beyond the everyday idea and raised the bar.  Great job on this.  The depth of field seems perfect and the lighting beautiful.  Great detail and colors too.  Hope this gets high ratings.</td>', 'There are a couple submitted that have used the magnifying glass idea but you went beyond the everyday idea and raised the bar.  Great job on this.  The depth of field seems perfect and the lighting beautiful.  Great detail and colors too.  Hope this gets high ratings.', '2004-08-17 12:22:27.000000', NULL, 1),
(863092, 97950, 4008, '<td valign="top">Looks very unreal to me, floating, without any reference to its environment. I agree it would fit well in encyclopedia type of book about botany, but I don''t find it an attractive image.</td>', 'Looks very unreal to me, floating, without any reference to its environment. I agree it would fit well in encyclopedia type of book about botany, but I don''t find it an attractive image.', '2004-08-17 12:35:44.000000', NULL, 1),
(863098, 97520, 18191, '<td valign="top">The background seems to be a little bit too busy in this shot.+</td>', 'The background seems to be a little bit too busy in this shot.+', '2004-08-17 12:39:36.000000', NULL, 1),
(863100, 97775, 18191, '<td valign="top">With an adjustment of curves, this could have been a very high rated shot. It is just a tad bit underexposed.</td>', 'With an adjustment of curves, this could have been a very high rated shot. It is just a tad bit underexposed.', '2004-08-17 12:41:34.000000', NULL, 1),
(863108, 97252, 19978, '<td valign="top">The low angle of the lighting really makes those vein shadows pop out. Very nice composition!</td>', 'The low angle of the lighting really makes those vein shadows pop out. Very nice composition!', '2004-08-17 12:44:52.000000', NULL, 1),
(863109, 97802, 2764, '<td valign="top">Absolutely exquisite!  I love the colors, the way they are dark in the center and fade to pale at the edges.  I love the lines I follow from top to bottom but the delicat curve of the lowerr stems leads me back into the picture.  I love the implied texture of the petalss which is really just a pattern, the pteals are smooth.  sooo nice - 10 of course</td>', 'Absolutely exquisite!  I love the colors, the way they are dark in the center and fade to pale at the edges.  I love the lines I follow from top to bottom but the delicat curve of the lowerr stems leads me back into the picture.  I love the implied texture of the petalss which is really just a pattern, the pteals are smooth.  sooo nice - 10 of course', '2004-08-17 12:44:55.000000', NULL, 1),
(863110, 97742, 18191, '<td valign="top">(Had to comment on my own name) The overexposed "High-Key" idea in this shot works very well. What makes this strong is the diagonal stretching across the image. Works very nicely. Good Job.</td>', '(Had to comment on my own name) The overexposed "High-Key" idea in this shot works very well. What makes this strong is the diagonal stretching across the image. Works very nicely. Good Job.', '2004-08-17 12:45:52.000000', NULL, 1),
(863112, 97722, 19978, '<td valign="top">A beautiful shot giving us a different perspective on the life-cycle of a flower. The details are very crisp and the lighting is excellent. Well done!</td>', 'A beautiful shot giving us a different perspective on the life-cycle of a flower. The details are very crisp and the lighting is excellent. Well done!', '2004-08-17 12:46:00.000000', NULL, 1),
(863113, 97858, 19978, '<td valign="top">The tones are a bit harsh and artificial looking, and the focus is not really crisp anyplace where I''d expect it to be.</td>', 'The tones are a bit harsh and artificial looking, and the focus is not really crisp anyplace where I''d expect it to be.', '2004-08-17 12:47:08.000000', NULL, 1),
(863115, 96652, 19978, '<td valign="top">I''m always a sucker for the simple and understated, and you''ve produced a very fine entry here. I love the pristine black background, and the angles you''ve created, and the use of negative space. I''d like to see the lone leaves a bit closer and more detailed though. Since they''re clearly the subject of interest that draws the eye, they leave me feeling a bit empty because there''s not much to study or hold my attention. I think the wide white frame is a little bit overkill too. A simple white line would have broadcast elegance. Great submission, but could have been much stronger, IMO.</td>', 'I''m always a sucker for the simple and understated, and you''ve produced a very fine entry here. I love the pristine black background, and the angles you''ve created, and the use of negative space. I''d like to see the lone leaves a bit closer and more detailed though. Since they''re clearly the subject of interest that draws the eye, they leave me feeling a bit empty because there''s not much to study or hold my attention. I think the wide white frame is a little bit overkill too. A simple white line would have broadcast elegance. Great submission, but could have been much stronger, IMO.', '2004-08-17 12:50:00.000000', NULL, 1),
(863119, 97732, 19978, '<td valign="top">This composition has an almost electric feel to it. Those wires or stems reaching out toward the watering can are spooky. I think the black background works well, but the leaves look a little messy or something, and detract from the otherwise simplistic beauty. It also seems as though you''re visible in the reflection off the metal can. Maybe use your timer to take yourself out of the shot, or do some cloning to remove the distractible elements of the reflection. 7</td>', 'This composition has an almost electric feel to it. Those wires or stems reaching out toward the watering can are spooky. I think the black background works well, but the leaves look a little messy or something, and detract from the otherwise simplistic beauty. It also seems as though you''re visible in the reflection off the metal can. Maybe use your timer to take yourself out of the shot, or do some cloning to remove the distractible elements of the reflection. 7', '2004-08-17 12:53:20.000000', NULL, 1),
(863120, 97190, 19978, '<td valign="top">While the motion creates a lovely effect, I have a hard time voting high on something that is possibly recognizable as life, but little else since no detail or context is evident (other than the title). I think this shot has high artistic merit, but I can only give it an average score in the challenge. (5)</td>', 'While the motion creates a lovely effect, I have a hard time voting high on something that is possibly recognizable as life, but little else since no detail or context is evident (other than the title). I think this shot has high artistic merit, but I can only give it an average score in the challenge. (5)', '2004-08-17 12:55:18.000000', NULL, 1),
(863133, 97950, 5822, '<td valign="top">I think the colors could use a bit more saturation to bring out their luster.</td>', 'I think the colors could use a bit more saturation to bring out their luster.', '2004-08-17 13:03:35.000000', NULL, 1),
(863134, 97723, 19978, '<td valign="top">Lots of potential but the focus is soft on your subject and the background is way too busy.</td>', 'Lots of potential but the focus is soft on your subject and the background is way too busy.', '2004-08-17 13:03:59.000000', NULL, 1),
(863138, 97979, 5822, '<td valign="top">I like the centered composition of weathered fence and shrubs but think it could use some more color, such as from a rose bush, or the like. In addition, I think the picture would have more impact if you shot it closer and were able to decrease the DOF so that the background weren''t so distracting.</td>', 'I like the centered composition of weathered fence and shrubs but think it could use some more color, such as from a rose bush, or the like. In addition, I think the picture would have more impact if you shot it closer and were able to decrease the DOF so that the background weren''t so distracting.', '2004-08-17 13:06:25.000000', NULL, 1),
(863141, 97011, 19978, '<td valign="top">I like this shot a great deal. The angle of the sunlight and shadows on the subjects is great. I wish you had cropped the rail and fence out though. I don''t think it adds anything to the photo and may indeed distract from the otherwise simple beauty. The deepness of the sky is wonderful. Bumping from a 6 to 7.</td>', 'I like this shot a great deal. The angle of the sunlight and shadows on the subjects is great. I wish you had cropped the rail and fence out though. I don''t think it adds anything to the photo and may indeed distract from the otherwise simple beauty. The deepness of the sky is wonderful. Bumping from a 6 to 7.', '2004-08-17 13:09:04.000000', NULL, 1),
(863143, 97303, 19978, '<td valign="top">Certainly a keeper that I''d be proud to hang anywhere in the house. The grass positively glows gold. Wonderful composition and crop. 7.</td>', 'Certainly a keeper that I''d be proud to hang anywhere in the house. The grass positively glows gold. Wonderful composition and crop. 7.', '2004-08-17 13:10:43.000000', NULL, 1),
(863146, 97975, 25378, '<td valign="top">I like this picture. The crop is nice, and the colors are beautiful, but I think that both leaves should have been in focus.</td>', 'I like this picture. The crop is nice, and the colors are beautiful, but I think that both leaves should have been in focus.', '2004-08-17 13:13:59.000000', NULL, 1),
(863148, 97975, 5822, '<td valign="top">Love how the composition brings out the delicate nature of this flower. This composition is outstanding! Lighting is very good too with the brightest part of the light directed towards the petals. Very well done.</td>', 'Love how the composition brings out the delicate nature of this flower. This composition is outstanding! Lighting is very good too with the brightest part of the light directed towards the petals. Very well done.', '2004-08-17 13:17:30.000000', NULL, 1),
(863150, 97666, 5822, '<td valign="top">There seems to be very little plant life in this picture and what little there is is blurred and doesn''t have much detail.</td>', 'There seems to be very little plant life in this picture and what little there is is blurred and doesn''t have much detail.', '2004-08-17 13:19:21.000000', NULL, 1),
(863151, 97801, 5822, '<td valign="top">Very nice color saturation but I think you overdid it with the dodging and burning.</td>', 'Very nice color saturation but I think you overdid it with the dodging and burning.', '2004-08-17 13:20:55.000000', NULL, 1),
(863153, 96797, 6845, '<td valign="top">NIIICCCCE!!!!!!!! I just don''t know what else to say. This is a great shot. The light, the composition, the colors, just everything is AWESOME. If this doesn''t win so help me.... Ok maybe that''s a little drastic, but I am pulling for this shot to take it all.</td>', 'NIIICCCCE!!!!!!!! I just don''t know what else to say. This is a great shot. The light, the composition, the colors, just everything is AWESOME. If this doesn''t win so help me.... Ok maybe that''s a little drastic, but I am pulling for this shot to take it all.', '2004-08-17 13:23:14.000000', NULL, 1),
(863154, 97348, 5822, '<td valign="top">Beautiful composition but I wish you had photograhed this scene at a differenet time of the day when shadows weren''t so abundant. It''s hard to see the rushing water run over  the rocks. Maybe a longer exposure would have improved this shot, imo.</td>', 'Beautiful composition but I wish you had photograhed this scene at a differenet time of the day when shadows weren''t so abundant. It''s hard to see the rushing water run over  the rocks. Maybe a longer exposure would have improved this shot, imo.', '2004-08-17 13:23:29.000000', NULL, 1),
(863156, 97428, 6845, '<td valign="top">Great tonal range and depth of field. I really enjoy this shot. It is very pleasing to look at. Just for my taste, I would like to see the middle of the flower more towards the bottom left. But that''s just me. Great image.</td>', 'Great tonal range and depth of field. I really enjoy this shot. It is very pleasing to look at. Just for my taste, I would like to see the middle of the flower more towards the bottom left. But that''s just me. Great image.', '2004-08-17 13:24:47.000000', NULL, 1),
(863157, 96645, 5822, '<td valign="top">Uneven lighting created a blue cast to the upper right.  Some fill on the leaves would help to have brought out some more detail  in them.</td>', 'Uneven lighting created a blue cast to the upper right.  Some fill on the leaves would help to have brought out some more detail  in them.', '2004-08-17 13:25:01.000000', NULL, 1),
(863159, 97190, 6845, '<td valign="top">I know some might find this too distracting or blurry, But I love it. It is a great abstract and a very different look for the challenge. Nice image.</td>', 'I know some might find this too distracting or blurry, But I love it. It is a great abstract and a very different look for the challenge. Nice image.', '2004-08-17 13:25:54.000000', NULL, 1),
(863170, 97904, 24715, '<td valign="top">Nice work!</td>', 'Nice work!', '2004-08-17 13:33:35.000000', NULL, 1),
(863172, 97992, 24715, '<td valign="top">Damn cars LOL</td>', 'Damn cars LOL', '2004-08-17 13:35:46.000000', NULL, 1),
(863179, 97812, 24715, '<td valign="top">That''s the spirit! Nice idea and the pic!</td>', 'That''s the spirit! Nice idea and the pic!', '2004-08-17 13:41:10.000000', NULL, 1),
(863184, 97426, 24715, '<td valign="top">Beautiful colors, very nice pic.</td>', 'Beautiful colors, very nice pic.', '2004-08-17 13:46:24.000000', NULL, 1),
(863185, 97830, 10867, '<td valign="top">The centre of attention in this photo really seems to be the falls rather than the plant life surrounding and in the midst of it.  The water is really well handled, incidentally!</td>', 'The centre of attention in this photo really seems to be the falls rather than the plant life surrounding and in the midst of it.  The water is really well handled, incidentally!', '2004-08-17 13:47:22.000000', NULL, 1),
(863186, 97515, 10867, '<td valign="top">BEautiful!</td>', 'BEautiful!', '2004-08-17 13:47:38.000000', NULL, 1),
(863188, 97828, 10867, '<td valign="top">Although it is much smaller than the trees, the focal point of this image is actually the bench.</td>', 'Although it is much smaller than the trees, the focal point of this image is actually the bench.', '2004-08-17 13:48:30.000000', NULL, 1),
(863189, 97781, 10867, '<td valign="top">Very clever and nicely executed.</td>', 'Very clever and nicely executed.', '2004-08-17 13:49:24.000000', NULL, 1),
(863191, 96723, 10867, '<td valign="top">Plant life isn''t really the subject of this clever and well execute image, unfortunately.</td>', 'Plant life isn''t really the subject of this clever and well execute image, unfortunately.', '2004-08-17 13:50:07.000000', NULL, 1),
(863197, 96652, 10867, '<td valign="top">Simple but elegant.   I wish that the whiish band around the base of the stem weren''t there. though.</td>', 'Simple but elegant.   I wish that the whiish band around the base of the stem weren''t there. though.', '2004-08-17 13:52:49.000000', NULL, 1),
(863198, 97750, 10867, '<td valign="top">Delightful!</td>', 'Delightful!', '2004-08-17 13:53:15.000000', NULL, 1),
(863199, 98016, 10867, '<td valign="top">Lovely.  Superb clarity, colours and textures.</td>', 'Lovely.  Superb clarity, colours and textures.', '2004-08-17 13:54:08.000000', NULL, 1),
(863209, 97943, 20204, '<td valign="top">The front flowers are outside the depth of field, which feels a bit awkward to me.  IYou''ve done a good job of isolating your subject  - nothing to distract from the field of flowers.</td>', 'The front flowers are outside the depth of field, which feels a bit awkward to me.  IYou''ve done a good job of isolating your subject  - nothing to distract from the field of flowers.', '2004-08-17 14:01:38.000000', NULL, 1),
(863213, 97944, 20204, '<td valign="top">I like your composition, but it seems detail was lost in the large white petals in the upper part of the frame.  It also seems that the lower center is out of the depth of field, so it would be good to stop down the aperture a bit.</td>', 'I like your composition, but it seems detail was lost in the large white petals in the upper part of the frame.  It also seems that the lower center is out of the depth of field, so it would be good to stop down the aperture a bit.', '2004-08-17 14:02:57.000000', NULL, 1),
(863216, 97305, 20204, '<td valign="top">Looks like the highlights are significantly blown out on this image and a lot of detail is lost in the leaves.  The subjects (deer) are also underexposed.  Given the lighting, it''s tough to say if you could have done anything better without a neutral density filter (assuming your camera can use filters).</td>', 'Looks like the highlights are significantly blown out on this image and a lot of detail is lost in the leaves.  The subjects (deer) are also underexposed.  Given the lighting, it''s tough to say if you could have done anything better without a neutral density filter (assuming your camera can use filters).', '2004-08-17 14:04:27.000000', NULL, 1),
(863220, 96929, 20204, '<td valign="top">Great detail, and excellent depth of field.  Not the most attractive image, but technically this is very well done in my eyes.</td>', 'Great detail, and excellent depth of field.  Not the most attractive image, but technically this is very well done in my eyes.', '2004-08-17 14:05:02.000000', NULL, 1),
(863234, 97297, 20204, '<td valign="top">I love the midground silhoutette, the background misting, and the foreground grass with excellent saturation.  The contrasting horizontal and vertical elements also play together nicely.  Great job!</td>', 'I love the midground silhoutette, the background misting, and the foreground grass with excellent saturation.  The contrasting horizontal and vertical elements also play together nicely.  Great job!', '2004-08-17 14:09:04.000000', NULL, 1),
(863236, 97858, 20204, '<td valign="top">Feels like this is color-cast or over saturated.  I''m also seeing a lack of sharpness which detracts from the image.</td>', 'Feels like this is color-cast or over saturated.  I''m also seeing a lack of sharpness which detracts from the image.', '2004-08-17 14:09:56.000000', NULL, 1),
(863238, 97576, 20204, '<td valign="top">Great clean background, nice choice of shutter speed; I like the water effect.</td>', 'Great clean background, nice choice of shutter speed; I like the water effect.', '2004-08-17 14:10:32.000000', NULL, 1),
(863242, 97948, 20204, '<td valign="top">I''m not crazy about the level of posterization here.  I think the background branch should either be more defined or cloned out completely.</td>', 'I''m not crazy about the level of posterization here.  I think the background branch should either be more defined or cloned out completely.', '2004-08-17 14:12:28.000000', NULL, 1),
(863245, 97829, 20204, '<td valign="top">Great lighting and detail in the leaf edges.  I like the clean background as well.</td>', 'Great lighting and detail in the leaf edges.  I like the clean background as well.', '2004-08-17 14:13:16.000000', NULL, 1),
(863251, 97350, 20204, '<td valign="top">I like the compotision, and colors.  Great depth of field as well!</td>', 'I like the compotision, and colors.  Great depth of field as well!', '2004-08-17 14:15:00.000000', NULL, 1),
(863254, 98011, 20204, '<td valign="top">Background feels very artificial to me...  Doesn''t seem to work well with the subject to me.</td>', 'Background feels very artificial to me...  Doesn''t seem to work well with the subject to me.', '2004-08-17 14:15:44.000000', NULL, 1),
(863256, 98020, 20204, '<td valign="top">I like to soft focus and lighting.  Not the most amazing subject, but it''s obvious you know how to handle a camera.  Nice work.</td>', 'I like to soft focus and lighting.  Not the most amazing subject, but it''s obvious you know how to handle a camera.  Nice work.', '2004-08-17 14:16:44.000000', NULL, 1),
(863259, 97923, 20204, '<td valign="top">Feels a bit washed out to me.  I think a saturation boost would help the aesthetics somewhat.</td>', 'Feels a bit washed out to me.  I think a saturation boost would help the aesthetics somewhat.', '2004-08-17 14:18:15.000000', NULL, 1),
(863264, 97851, 20204, '<td valign="top">I love the rich blues in the top of the image and the greens in the bottom.  You''ve got a perfect depth of field in here which makes for a complimentary but not distracting backdrop.  Great work!</td>', 'I love the rich blues in the top of the image and the greens in the bottom.  You''ve got a perfect depth of field in here which makes for a complimentary but not distracting backdrop.  Great work!', '2004-08-17 14:19:21.000000', NULL, 1),
(863272, 97347, 20204, '<td valign="top">Beautiful composition - I love the way you placed the plants at 90 degree angles , and your lighting is excellent.</td>', 'Beautiful composition - I love the way you placed the plants at 90 degree angles , and your lighting is excellent.', '2004-08-17 14:21:54.000000', NULL, 1),
(863307, 98023, 13365, '<td valign="top">simple, yet effective! 8</td>', 'simple, yet effective! 8', '2004-08-17 14:46:06.000000', NULL, 1),
(863311, 96723, 13365, '<td valign="top">very creative, only thing i would of like is a little more headroom on top!! 8</td>', 'very creative, only thing i would of like is a little more headroom on top!! 8', '2004-08-17 14:47:00.000000', NULL, 1),
(863316, 97542, 25143, '<td valign="top">why such a philosophical title? I fail to see the connection</td>', 'why such a philosophical title? I fail to see the connection', '2004-08-17 14:51:14.000000', NULL, 1),
(863320, 97801, 25143, '<td valign="top">I find the hanging leaf somewhat distracting from the general optimism of the picture - great yellow/blue intensity</td>', 'I find the hanging leaf somewhat distracting from the general optimism of the picture - great yellow/blue intensity', '2004-08-17 14:53:53.000000', NULL, 1),
(863322, 97883, 25143, '<td valign="top">this picture could turn me into a hosta fan.. very nice composition and lighting</td>', 'this picture could turn me into a hosta fan.. very nice composition and lighting', '2004-08-17 14:55:16.000000', NULL, 1),
(863323, 97948, 11738, '<td valign="top">Interesting high key approach, but feels a tad overdone.  That blue halo around the leaf that is out of focus is very distracting.  Also, what caused that bluish shadow in the upper right quadrant?  Another branch?  I also think that a black line for your frame may have been more appropriate.</td>', 'Interesting high key approach, but feels a tad overdone.  That blue halo around the leaf that is out of focus is very distracting.  Also, what caused that bluish shadow in the upper right quadrant?  Another branch?  I also think that a black line for your frame may have been more appropriate.', '2004-08-17 14:55:23.000000', NULL, 1),
(863330, 97902, 25143, '<td valign="top">the background colour does not work too well, and what''s the shadow on the bottom center - I like the composition though</td>', 'the background colour does not work too well, and what''s the shadow on the bottom center - I like the composition though', '2004-08-17 14:57:27.000000', NULL, 1),
(863331, 97538, 25143, '<td valign="top">if only the leaf could be focused too ..</td>', 'if only the leaf could be focused too ..', '2004-08-17 14:58:05.000000', NULL, 1),
(863332, 97775, 11738, '<td valign="top">Super low light image.  Really shows that this flower has finished its useful purpose and is now fading into nothingness.  Nice composition and excellent selection of DOF.  One of my favourites in the challenge.</td>', 'Super low light image.  Really shows that this flower has finished its useful purpose and is now fading into nothingness.  Nice composition and excellent selection of DOF.  One of my favourites in the challenge.', '2004-08-17 14:58:29.000000', NULL, 1),
(863333, 97604, 25143, '<td valign="top">too muted colors and the focus area is not differentiated enough from the blurry surroundings</td>', 'too muted colors and the focus area is not differentiated enough from the blurry surroundings', '2004-08-17 14:59:15.000000', NULL, 1),
(863335, 97968, 25143, '<td valign="top">why not leave it in colour - it would have been ''almost b&amp;w'' and more intriguing to me</td>', 'why not leave it in colour - it would have been ''almost b&w'' and more intriguing to me', '2004-08-17 15:00:29.000000', NULL, 1),
(863336, 97923, 11738, '<td valign="top">Nice flower, but your light is a tad too harsh.  I know it''s not easy outside, but the sunlight might have been filtered somewhat to soften this image atad.</td>', 'Nice flower, but your light is a tad too harsh.  I know it''s not easy outside, but the sunlight might have been filtered somewhat to soften this image atad.', '2004-08-17 15:00:32.000000', NULL, 1),
(863340, 97608, 25143, '<td valign="top">too bad the background is too busy, nice bark shedding</td>', 'too bad the background is too busy, nice bark shedding', '2004-08-17 15:02:01.000000', NULL, 1),
(863341, 96919, 25143, '<td valign="top">but where is the fourth stem??</td>', 'but where is the fourth stem??', '2004-08-17 15:02:42.000000', NULL, 1),
(863342, 97576, 11738, '<td valign="top">I would have cropped this closer, cropping out more of the watering can and concentrating more interest on the flower and falling water.  Could also have been a tad brighter: light sort of flat, causing flower not "popping" off the image.  Good work and keep experimenting.</td>', 'I would have cropped this closer, cropping out more of the watering can and concentrating more interest on the flower and falling water.  Could also have been a tad brighter: light sort of flat, causing flower not "popping" off the image.  Good work and keep experimenting.', '2004-08-17 15:03:00.000000', NULL, 1),
