(863356, 97723, 25143, '<td valign="top">the colors are off and the broken stem right across the main image is distracting</td>', 'the colors are off and the broken stem right across the main image is distracting', '2004-08-17 15:07:44.000000', NULL, 1),
(863358, 97966, 25143, '<td valign="top">why not leave the color - this is somewhat neither BW nor pastel - I like the overall composition though</td>', 'why not leave the color - this is somewhat neither BW nor pastel - I like the overall composition though', '2004-08-17 15:09:21.000000', NULL, 1),
(863359, 97947, 25143, '<td valign="top">not enough main focus to look at</td>', 'not enough main focus to look at', '2004-08-17 15:10:08.000000', NULL, 1),
(863360, 97742, 25143, '<td valign="top">get the colours back and I vote higher.. I like the angle of view and reflections very much</td>', 'get the colours back and I vote higher.. I like the angle of view and reflections very much', '2004-08-17 15:11:06.000000', NULL, 1),
(863361, 97336, 25143, '<td valign="top">amusing idea</td>', 'amusing idea', '2004-08-17 15:11:32.000000', NULL, 1),
(863362, 97297, 11738, '<td valign="top">Interesting image but your horizon is crooked: higher to left and lower in the right.  It''s a good idea to ALWAYS check your horizons before submitting.  I think it''s made even more vident by the lawn patterns.  Love the foggy look in the back.</td>', 'Interesting image but your horizon is crooked: higher to left and lower in the right.  It''s a good idea to ALWAYS check your horizons before submitting.  I think it''s made even more vident by the lawn patterns.  Love the foggy look in the back.', '2004-08-17 15:11:57.000000', NULL, 1),
(863364, 97782, 11738, '<td valign="top">Too bad about the leaf defects.  A perfect leaf would have given you a +1 in score.</td>', 'Too bad about the leaf defects.  A perfect leaf would have given you a +1 in score.', '2004-08-17 15:12:35.000000', NULL, 1),
(863365, 97992, 25143, '<td valign="top">here''s where one needs a friend to hold a plain sheet behind the very nice flowers to neutralize the background..</td>', 'here''s where one needs a friend to hold a plain sheet behind the very nice flowers to neutralize the background..', '2004-08-17 15:12:40.000000', NULL, 1),
(863368, 97958, 25143, '<td valign="top">washed out colours - why not underexpose this view?</td>', 'washed out colours - why not underexpose this view?', '2004-08-17 15:13:15.000000', NULL, 1),
(863369, 97702, 25143, '<td valign="top">terrific spot clarity !! nice choice of depth of field</td>', 'terrific spot clarity !! nice choice of depth of field', '2004-08-17 15:13:51.000000', NULL, 1),
(863371, 98007, 25143, '<td valign="top">weird color reduction confuses but does not improve the photo</td>', 'weird color reduction confuses but does not improve the photo', '2004-08-17 15:14:25.000000', NULL, 1),
(863372, 97799, 25143, '<td valign="top">great shadows</td>', 'great shadows', '2004-08-17 15:14:43.000000', NULL, 1),
(863374, 97979, 25143, '<td valign="top">nice garden but a bit bland as a composition and too much competing detail - i.e. either too busy or not busy enough</td>', 'nice garden but a bit bland as a composition and too much competing detail - i.e. either too busy or not busy enough', '2004-08-17 15:16:19.000000', NULL, 1),
(863377, 97797, 25143, '<td valign="top">gorgeous blue</td>', 'gorgeous blue', '2004-08-17 15:16:38.000000', NULL, 1),
