(863380, 97718, 25143, '<td valign="top">why wilt thou not leave the colous in the view??</td>', 'why wilt thou not leave the colous in the view??', '2004-08-17 15:17:49.000000', NULL, 1),
(863381, 98022, 25143, '<td valign="top">fuzzy bottom - why not cut the view in order to get more focus</td>', 'fuzzy bottom - why not cut the view in order to get more focus', '2004-08-17 15:18:48.000000', NULL, 1),
(863382, 97428, 11738, '<td valign="top">Awesome tones in this B&amp;W.  The best B&amp;W flower for this challenge.  Good focus too.</td>', 'Awesome tones in this B&W.  The best B&W flower for this challenge.  Good focus too.', '2004-08-17 15:18:54.000000', NULL, 1),
(863383, 97904, 11738, '<td valign="top">Almost has a "casket shot" feel.</td>', 'Almost has a "casket shot" feel.', '2004-08-17 15:19:24.000000', NULL, 1),
(863384, 97520, 25143, '<td valign="top">too much shadow patterning without obvious and visible reason</td>', 'too much shadow patterning without obvious and visible reason', '2004-08-17 15:19:28.000000', NULL, 1),
(863385, 97903, 25143, '<td valign="top">overexposed and therefore not moody enough</td>', 'overexposed and therefore not moody enough', '2004-08-17 15:19:57.000000', NULL, 1),
(863386, 97891, 25143, '<td valign="top">chic idea - you need to dust the cobwebs off though ...</td>', 'chic idea - you need to dust the cobwebs off though ...', '2004-08-17 15:20:38.000000', NULL, 1),
(863388, 97041, 25143, '<td valign="top">fitting title - great picture</td>', 'fitting title - great picture', '2004-08-17 15:21:24.000000', NULL, 1),
(863389, 97443, 11738, '<td valign="top">A bit small.  You could have enlarged this shot another 95 pixels to reach the 640 pixel size.  Interesting colours in the leaf.</td>', 'A bit small.  You could have enlarged this shot another 95 pixels to reach the 640 pixel size.  Interesting colours in the leaf.', '2004-08-17 15:21:37.000000', NULL, 1),
(863390, 97330, 25143, '<td valign="top">the background is distracting - the reflection is very nice though</td>', 'the background is distracting - the reflection is very nice though', '2004-08-17 15:22:02.000000', NULL, 1),
(863393, 97789, 25143, '<td valign="top">why not keep the colors? The idea is funny</td>', 'why not keep the colors? The idea is funny', '2004-08-17 15:23:21.000000', NULL, 1),
(863394, 97470, 11738, '<td valign="top">Cool shot, but too bad about those intruding petals on the bottom.  I would have left out the border.</td>', 'Cool shot, but too bad about those intruding petals on the bottom.  I would have left out the border.', '2004-08-17 15:23:32.000000', NULL, 1),
(863395, 98013, 25143, '<td valign="top">too much fuzz around the borders and so-so lighting</td>', 'too much fuzz around the borders and so-so lighting', '2004-08-17 15:24:06.000000', NULL, 1),
(863396, 97747, 15832, '<td valign="top">Nice colours and good combination.</td>', 'Nice colours and good combination.', '2004-08-17 15:24:39.000000', NULL, 1),
(863397, 97921, 25143, '<td valign="top">one-sided color scheme competing with a busy but not interesting enough contrast of sky and silhouette of trees</td>', 'one-sided color scheme competing with a busy but not interesting enough contrast of sky and silhouette of trees', '2004-08-17 15:25:09.000000', NULL, 1),
(863398, 97331, 25143, '<td valign="top">the old idea of wet look revisited, how about a more sober title to counterbalance</td>', 'the old idea of wet look revisited, how about a more sober title to counterbalance', '2004-08-17 15:26:30.000000', NULL, 1),
(863400, 97676, 11738, '<td valign="top">Awesome colours</td>', 'Awesome colours', '2004-08-17 15:26:40.000000', NULL, 1),
(863401, 97461, 25143, '<td valign="top">what are the shadows in the floral center? too much distraction</td>', 'what are the shadows in the floral center? too much distraction', '2004-08-17 15:27:19.000000', NULL, 1),
(863403, 97775, 25143, '<td valign="top">why such a religious title - too much unfocused area</td>', 'why such a religious title - too much unfocused area', '2004-08-17 15:28:03.000000', NULL, 1),
(863404, 97751, 25143, '<td valign="top">cool idea!! but a bit overexposed</td>', 'cool idea!! but a bit overexposed', '2004-08-17 15:28:33.000000', NULL, 1),
(863409, 97293, 25143, '<td valign="top">neat extreme contrast between focus and non</td>', 'neat extreme contrast between focus and non', '2004-08-17 15:29:48.000000', NULL, 1),
(863410, 97177, 25143, '<td valign="top">great lighting and idea</td>', 'great lighting and idea', '2004-08-17 15:30:16.000000', NULL, 1),
(863413, 97782, 25143, '<td valign="top">too much background information competing with a very nice subject view</td>', 'too much background information competing with a very nice subject view', '2004-08-17 15:31:14.000000', NULL, 1),
(863415, 96723, 25143, '<td valign="top">FUN and a well done image - did you end up eating the worms??</td>', 'FUN and a well done image - did you end up eating the worms??', '2004-08-17 15:32:52.000000', NULL, 1),
(863416, 97722, 25143, '<td valign="top">nicely weird colors</td>', 'nicely weird colors', '2004-08-17 15:33:17.000000', NULL, 1),
(863418, 97801, 4226, '<td valign="top">LIke the burning of the sky and clouds</td>', 'LIke the burning of the sky and clouds', '2004-08-17 15:37:33.000000', NULL, 1),
(863428, 97937, 15832, '<td valign="top">Smooth... I like the green and the flow on the water. 7</td>', 'Smooth... I like the green and the flow on the water. 7', '2004-08-17 15:48:16.000000', NULL, 1),
(863431, 96655, 20204, '<td valign="top">I''d like to see the cropping tighter on top, and a bit tighter on the left to maintain aspect ratio.  The vast sky draws my eye away from the river and trees which are otherwise beautiful subjects.</td>', 'I''d like to see the cropping tighter on top, and a bit tighter on the left to maintain aspect ratio.  The vast sky draws my eye away from the river and trees which are otherwise beautiful subjects.', '2004-08-17 15:51:45.000000', NULL, 1),
(863432, 97336, 15832, '<td valign="top">hehe. Cool idea with the shadow!  <br/>I wonder how it would have looked in colours. White black and green.<br/>Creative idea.</td>', 'hehe. Cool idea with the shadow!  I wonder how it would have looked in colours. White black and green.Creative idea.', '2004-08-17 15:51:49.000000', NULL, 1),
(863437, 98018, 20204, '<td valign="top">I think a lower point of view would help to emphsize the fence more as a subject, thus creating a stronger image.  Great saturation - not too much, yet visually striking colors.</td>', 'I think a lower point of view would help to emphsize the fence more as a subject, thus creating a stronger image.  Great saturation - not too much, yet visually striking colors.', '2004-08-17 15:55:19.000000', NULL, 1),
(863438, 97875, 20204, '<td valign="top">Feels a touch overexposed or washed out.  A bit of sharpness would help...</td>', 'Feels a touch overexposed or washed out.  A bit of sharpness would help...', '2004-08-17 15:56:51.000000', NULL, 1),
(863440, 97558, 15832, '<td valign="top">Very clever and nice expression on the seasons. Good job. 8</td>', 'Very clever and nice expression on the seasons. Good job. 8', '2004-08-17 15:58:06.000000', NULL, 1),
(863445, 97551, 14603, '<td valign="top">The blurred background works very well at highlighting the subject.<br/>Colours mix well and the composition is first class....8</td>', 'The blurred background works very well at highlighting the subject.Colours mix well and the composition is first class....8', '2004-08-17 16:03:45.000000', NULL, 1),
(863446, 97979, 15832, '<td valign="top">It always happend (as far as i know) that, when the image is so small it gets voted down.<br/>This is a really nice photo and good framing but i think you would have scored higher if the size was bigger.   Probably heard that already :)</td>', 'It always happend (as far as i know) that, when the image is so small it gets voted down.This is a really nice photo and good framing but i think you would have scored higher if the size was bigger.   Probably heard that already :)', '2004-08-17 16:05:48.000000', NULL, 1),
(863447, 97190, 14603, '<td valign="top">Beautifully abstract and something I would like to see succeeding in this challenge.<br/>Good luck</td>', 'Beautifully abstract and something I would like to see succeeding in this challenge.Good luck', '2004-08-17 16:05:59.000000', NULL, 1),
(863448, 97961, 20204, '<td valign="top">This image is too small, and appears out of focus.</td>', 'This image is too small, and appears out of focus.', '2004-08-17 16:07:08.000000', NULL, 1),
(863450, 97598, 20204, '<td valign="top">Not enough contrast in the design elements, sharpness isn''t enough to bring out the foreground detail.</td>', 'Not enough contrast in the design elements, sharpness isn''t enough to bring out the foreground detail.', '2004-08-17 16:08:06.000000', NULL, 1),
(863451, 97994, 20204, '<td valign="top">The subject isn''t occupying enough of the frame; Instead of focusing on the bees and flower I''m bouncing around the image trying to make out detail in the other shapes.</td>', 'The subject isn''t occupying enough of the frame; Instead of focusing on the bees and flower I''m bouncing around the image trying to make out detail in the other shapes.', '2004-08-17 16:08:58.000000', NULL, 1),
(863452, 97961, 15832, '<td valign="top">Any smaller photo and you got your self a stamp :)<br/>Would have liked to see it bigger.</td>', 'Any smaller photo and you got your self a stamp :)Would have liked to see it bigger.', '2004-08-17 16:09:19.000000', NULL, 1),
(863453, 97631, 20204, '<td valign="top">There is too much brightness in the background for my liking - competes with the foreground.  The cropping is a bit awkward as well - no strong subject pops out at me.</td>', 'There is too much brightness in the background for my liking - competes with the foreground.  The cropping is a bit awkward as well - no strong subject pops out at me.', '2004-08-17 16:09:57.000000', NULL, 1),
(863455, 97744, 14603, '<td valign="top">Beautifully composed..perfectly sharp and wonderful contrast.<br/>Quality work....9</td>', 'Beautifully composed..perfectly sharp and wonderful contrast.Quality work....9', '2004-08-17 16:10:38.000000', NULL, 1),
(863456, 97918, 15832, '<td valign="top">Great landscape photo!</td>', 'Great landscape photo!', '2004-08-17 16:11:00.000000', NULL, 1),
(863458, 97428, 20204, '<td valign="top">Wow...  This is one of the most beautiful images I have seen - you''d be crazy not to have this on DPC prints.  A touch more depth of field to clean up the foreground blurring would have won this image a 10 from me.  Even with the foreground issue I find myself staring at it...  Excellent!!</td>', 'Wow...  This is one of the most beautiful images I have seen - you''d be crazy not to have this on DPC prints.  A touch more depth of field to clean up the foreground blurring would have won this image a 10 from me.  Even with the foreground issue I find myself staring at it...  Excellent!!', '2004-08-17 16:12:33.000000', NULL, 1),
(863459, 97828, 20204, '<td valign="top">I would like to see a slightly lower point of view to emphasize the bench a bit more, but overall this is a gorgeous scene.  I like your choice of b/w for it as well - conveys a mood of solitude to me.  Great work! [8]</td>', 'I would like to see a slightly lower point of view to emphasize the bench a bit more, but overall this is a gorgeous scene.  I like your choice of b/w for it as well - conveys a mood of solitude to me.  Great work! [8]', '2004-08-17 16:13:36.000000', NULL, 1),
(863461, 97331, 20204, '<td valign="top">Razor sharp image, and an excellent job on a clean background.  Nice work!</td>', 'Razor sharp image, and an excellent job on a clean background.  Nice work!', '2004-08-17 16:14:21.000000', NULL, 1),
(863463, 98011, 15832, '<td valign="top">Wow... My personal top 5 in this challenge. 8</td>', 'Wow... My personal top 5 in this challenge. 8', '2004-08-17 16:15:14.000000', NULL, 1),
(863464, 97757, 20204, '<td valign="top">I having a bit of trouble finding anything in focus on this image.  There is massive foreground blurring on one of the flowers which is very distracting.  might want to check the minimum focusing distance of your lens.</td>', 'I having a bit of trouble finding anything in focus on this image.  There is massive foreground blurring on one of the flowers which is very distracting.  might want to check the minimum focusing distance of your lens.', '2004-08-17 16:15:37.000000', NULL, 1),
(863466, 97189, 20204, '<td valign="top">This is bordering on impressionistic to me...  The glare and darkness makes it very difficult to tell what the subjects are.  I''m also not seeing any strong subject being conveyed here.</td>', 'This is bordering on impressionistic to me...  The glare and darkness makes it very difficult to tell what the subjects are.  I''m also not seeing any strong subject being conveyed here.', '2004-08-17 16:16:39.000000', NULL, 1),
(863468, 97801, 21430, '<td valign="top">Nice use of the burn tool. This is a nioce caputre as well, although it is also a very commong sunflower photograph. It would be interesting to see more of the plant or a different angle as this is also a fairly common angle for photographing this type of flower.<br/> <br/>  The color is very rich and quite attractive as well. I could see this in a small frame on a desk or someplace similar.</td>', 'Nice use of the burn tool. This is a nioce caputre as well, although it is also a very commong sunflower photograph. It would be interesting to see more of the plant or a different angle as this is also a fairly common angle for photographing this type of flower.   The color is very rich and quite attractive as well. I could see this in a small frame on a desk or someplace similar.', '2004-08-17 16:17:23.000000', NULL, 1),
(863469, 96961, 20204, '<td valign="top">Not enough depth of field to keep all of the subjects within focus here.  There is also a washed out quality.  Finally, those flowers representing "death" are a bit unatractive to me - they look a bit like used kleenex tissues...  I knwo reality isn''t always beautiful, but to get past that I''d need the central flower to stand stronger on its own as a subject.</td>', 'Not enough depth of field to keep all of the subjects within focus here.  There is also a washed out quality.  Finally, those flowers representing "death" are a bit unatractive to me - they look a bit like used kleenex tissues...  I knwo reality isn''t always beautiful, but to get past that I''d need the central flower to stand stronger on its own as a subject.', '2004-08-17 16:18:24.000000', NULL, 1),
(863471, 97997, 20204, '<td valign="top">This image is very busy to me.  I''d suggest trying to find something you want to express from the scene and try to find ways of emphasizing it so that everything didn''t get lost in the image.</td>', 'This image is very busy to me.  I''d suggest trying to find something you want to express from the scene and try to find ways of emphasizing it so that everything didn''t get lost in the image.', '2004-08-17 16:19:13.000000', NULL, 1),
(863473, 97958, 20204, '<td valign="top">The highlights are just too bright for me here.  It''s nice to have a clean background, but this feels like it was done at the expense of a significant number of pixels.</td>', 'The highlights are just too bright for me here.  It''s nice to have a clean background, but this feels like it was done at the expense of a significant number of pixels.', '2004-08-17 16:20:01.000000', NULL, 1),
(863474, 98007, 20204, '<td valign="top">Overall, this image feels very dark and underexposed.  I think a touch of sharpening would do wonders.  If you shot this in RAW, it may help to boost the gamma or brightness a touch if it could be done without blowing out the highlights.</td>', 'Overall, this image feels very dark and underexposed.  I think a touch of sharpening would do wonders.  If you shot this in RAW, it may help to boost the gamma or brightness a touch if it could be done without blowing out the highlights.', '2004-08-17 16:20:59.000000', NULL, 1),
(863475, 97842, 20204, '<td valign="top">I think the subject is interesting, but as it is presented here much of the intricate detail is lost in the darker lower half of the image.  Maybe shooting from a lower point of view would brighten the lower part of the image and bring more contrast to the dead branches?</td>', 'I think the subject is interesting, but as it is presented here much of the intricate detail is lost in the darker lower half of the image.  Maybe shooting from a lower point of view would brighten the lower part of the image and bring more contrast to the dead branches?', '2004-08-17 16:22:11.000000', NULL, 1),
(863477, 97915, 20204, '<td valign="top">This is screaming to have its saturation boosted.  It also needs a bit more depth of field to keep the branch in focus, or more evenly focused.  I think overexposure is your biggest obstacle on this shot.  Bringing a folding car reflector with you to block the direct sunlight may help to get the tonal range down into a level the camera could handle.</td>', 'This is screaming to have its saturation boosted.  It also needs a bit more depth of field to keep the branch in focus, or more evenly focused.  I think overexposure is your biggest obstacle on this shot.  Bringing a folding car reflector with you to block the direct sunlight may help to get the tonal range down into a level the camera could handle.', '2004-08-17 16:23:49.000000', NULL, 1),
(863479, 96797, 20204, '<td valign="top">I love the choice of colors in this image, and overall the simplicity.  You''ve chosen a strong subject and successfully eliminated anything distracting from the image.  Well done!</td>', 'I love the choice of colors in this image, and overall the simplicity.  You''ve chosen a strong subject and successfully eliminated anything distracting from the image.  Well done!', '2004-08-17 16:24:38.000000', NULL, 1),
(863480, 97982, 20204, '<td valign="top">I love the lighting in this image - such intricate detail!</td>', 'I love the lighting in this image - such intricate detail!', '2004-08-17 16:25:15.000000', NULL, 1),
(863482, 96652, 20204, '<td valign="top">This picture epitomizes the concept of less is more.  Excellent!  If I were you, I''d put this on DPC prints.</td>', 'This picture epitomizes the concept of less is more.  Excellent!  If I were you, I''d put this on DPC prints.', '2004-08-17 16:25:57.000000', NULL, 1),
(863483, 97190, 20204, '<td valign="top">I''m not normally into impressionistic / abstract styles, but the colors and sense of motion in this really captured my attention.  I applaud you for doing somethign different here, and doing it well. [7]</td>', 'I''m not normally into impressionistic / abstract styles, but the colors and sense of motion in this really captured my attention.  I applaud you for doing somethign different here, and doing it well. [7]', '2004-08-17 16:26:59.000000', NULL, 1),
(863484, 97297, 14603, '<td valign="top">Good composition and the faded background really emphasises the distance between the trees.<br/>Nicely done...9</td>', 'Good composition and the faded background really emphasises the distance between the trees.Nicely done...9', '2004-08-17 16:27:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(863487, 96652, 14603, '<td valign="top">Good use of composition and light give this simple image impact.</td>', 'Good use of composition and light give this simple image impact.', '2004-08-17 16:32:43.000000', NULL, 1),
(863492, 97942, 14603, '<td valign="top">Nice use of selective desat..certainly works for the challenge.</td>', 'Nice use of selective desat..certainly works for the challenge.', '2004-08-17 16:38:13.000000', NULL, 1),
(863497, 97763, 14603, '<td valign="top">Nice use of select desat which works well for the challenge</td>', 'Nice use of select desat which works well for the challenge', '2004-08-17 16:41:54.000000', NULL, 1),
(863499, 97811, 18197, '<td valign="top">Nice composition which clearly met the challenge. Colors are good. Comp is fine. I think greater DOF would have improved it but that''s probaby a matter of taste.</td>', 'Nice composition which clearly met the challenge. Colors are good. Comp is fine. I think greater DOF would have improved it but that''s probaby a matter of taste.', '2004-08-17 16:44:08.000000', NULL, 1),
(863500, 96655, 14603, '<td valign="top">Nice landscape which would probably convert well to oils</td>', 'Nice landscape which would probably convert well to oils', '2004-08-17 16:44:38.000000', NULL, 1),
(863504, 97485, 14603, '<td valign="top">Nice lighting technique..the image really suits the soft focus feel.</td>', 'Nice lighting technique..the image really suits the soft focus feel.', '2004-08-17 16:47:27.000000', NULL, 1),
(863506, 97550, 18197, '<td valign="top">I like this a great deal. Assuming it was all done in the camera, the luminescent fog is terrific. The focus is splendid. Levels are very good. Colors are great. Among my top 10 picks so far.</td>', 'I like this a great deal. Assuming it was all done in the camera, the luminescent fog is terrific. The focus is splendid. Levels are very good. Colors are great. Among my top 10 picks so far.', '2004-08-17 16:50:22.000000', NULL, 1),
(863507, 97982, 14603, '<td valign="top">I really like the simplicity of this..the backlighting and shallow dof help to emphasise the foreground stem..lovely composition also...9</td>', 'I really like the simplicity of this..the backlighting and shallow dof help to emphasise the foreground stem..lovely composition also...9', '2004-08-17 16:51:13.000000', NULL, 1),
(863509, 97732, 18197, '<td valign="top">I like the high contrast of this image. The gold tones and reflections are pleasing (except the reflection of the photographer). Focus is good. Comp''s fine. I am bothered by the fact that the post and can seem to be floating in air. I can see why you cropped it the way you did to get the right balance, but it still bothers me for some reason.</td>', 'I like the high contrast of this image. The gold tones and reflections are pleasing (except the reflection of the photographer). Focus is good. Comp''s fine. I am bothered by the fact that the post and can seem to be floating in air. I can see why you cropped it the way you did to get the right balance, but it still bothers me for some reason.', '2004-08-17 16:54:15.000000', NULL, 1),
(863510, 97948, 19322, '<td valign="top">More dashes of background color would help give a more balanced feel, I think.</td>', 'More dashes of background color would help give a more balanced feel, I think.', '2004-08-17 16:54:36.000000', NULL, 1),
(863512, 97802, 18197, '<td valign="top">I like the pattern of the stem against the backdrop of the flowers. Focus works nicely. DOF a bit too shallow to catch most of the stem. Beautiful photo. Congratulations.</td>', 'I like the pattern of the stem against the backdrop of the flowers. Focus works nicely. DOF a bit too shallow to catch most of the stem. Beautiful photo. Congratulations.', '2004-08-17 16:55:41.000000', NULL, 1),
(863514, 97921, 18197, '<td valign="top">I really don''t feel the tie in to the theme very strongly. Otherwise a nice photo.</td>', 'I really don''t feel the tie in to the theme very strongly. Otherwise a nice photo.', '2004-08-17 16:56:18.000000', NULL, 1),
(863516, 97330, 18197, '<td valign="top">Gorgeous. I love everything about it. Obviously the strongest feature is the lighting and razor sharp focus on the subject. Centered comp seems to work due to negative space in the background. Hope it does well inthe scoring.</td>', 'Gorgeous. I love everything about it. Obviously the strongest feature is the lighting and razor sharp focus on the subject. Centered comp seems to work due to negative space in the background. Hope it does well inthe scoring.', '2004-08-17 16:57:42.000000', NULL, 1),
