(869111, 97915, 24546, '<td valign="top">Great idea - but there is so much sun on the apple that it washes out the colors at this exposure.</td>', 'Great idea - but there is so much sun on the apple that it washes out the colors at this exposure.', '2004-08-21 01:34:29.000000', NULL, 1),
