(870050, 97558, 17033, '<td valign="top">Colour, composition, concept all spot on here. Deserves to be a top scorer.</td>', 'Colour, composition, concept all spot on here. Deserves to be a top scorer.', '2004-08-22 06:00:54.000000', NULL, 1),
(870105, 97520, 15002, '<td valign="top">nice composition, a bit hot</td>', 'nice composition, a bit hot', '2004-08-22 09:48:58.000000', NULL, 1),
(870108, 97744, 15002, '<td valign="top">Nicely done B&amp;W.   I really like the lighting.  The DOF is a bit off,  with part of the backgound flower in focus.  IMHO it should be all or none.</td>', 'Nicely done B&W.   I really like the lighting.  The DOF is a bit off,  with part of the backgound flower in focus.  IMHO it should be all or none.', '2004-08-22 09:58:54.000000', NULL, 1),
(870109, 97972, 15002, '<td valign="top">Too busy, too many subjects.  Perhaps get in closer and focus attention to one subject.</td>', 'Too busy, too many subjects.  Perhaps get in closer and focus attention to one subject.', '2004-08-22 10:04:36.000000', NULL, 1),
(870111, 97428, 15002, '<td valign="top">the texture is excellent</td>', 'the texture is excellent', '2004-08-22 10:05:59.000000', NULL, 1),
(870113, 97979, 15002, '<td valign="top">Cropped like this, the fence draws my attention.  How about getting closer and focusing on a main subject.</td>', 'Cropped like this, the fence draws my attention.  How about getting closer and focusing on a main subject.', '2004-08-22 10:08:45.000000', NULL, 1),
(870114, 97994, 15002, '<td valign="top">Crop tighter, remember the rule of thirds</td>', 'Crop tighter, remember the rule of thirds', '2004-08-22 10:10:07.000000', NULL, 1),
