(870121, 97836, 11897, '<td valign="top">Clever idea, not unique in this challenge but the best one. 10</td>', 'Clever idea, not unique in this challenge but the best one. 10', '2004-08-22 10:22:09.000000', NULL, 1),
(870122, 97722, 11897, '<td valign="top">good detail, fine picture 9</td>', 'good detail, fine picture 9', '2004-08-22 10:22:33.000000', NULL, 1),
(870123, 97550, 11897, '<td valign="top">A beautiful shot 9</td>', 'A beautiful shot 9', '2004-08-22 10:23:12.000000', NULL, 1),
